      const value=number=>number.toFixed(2),points=data.points.map(([x,y])=>({x:300+x*170,y:255+y*170})),label=(x,y,text,colour='#302942',font=27)=>`<text x="${value(x)}" y="${value(y)}" text-anchor="middle" font-family="Arial,sans-serif" font-size="${font}" font-weight="700" fill="${colour}" stroke="#fff" stroke-width="5" paint-order="stroke">${escapeHtml(text)}</text>`;
