      const setup=equation([...data.known.map(angle=>`${angle}° +`),subject,'=',`${data.total}°`],'setup'),second=step(2,'Bina persamaan sudut',`${external?'<p>Namakan sudut pedalaman pada bucu lanjutan sebagai y.</p>':''}${setup}${showAnswer?equation([`${data.knownSum}° +`,subject,'=',`${data.total}°`],'collect'):'<p>Tambah semua sudut yang diberi dahulu. Nilai sudut akhir belum dipaparkan.</p>'}`,'equation');
      const third=step(3,`Asingkan ${subject}`,showAnswer?`${equation([subject,'=',`${data.total}° − ${data.knownSum}°`],'subtract')}${equation([subject,'=',`${data.interior}°`],'interior-result')}<aside class="subject-annotation"><span aria-hidden="true">←</span>Tolak hasil tambah sudut yang diberi daripada kedua-dua belah persamaan.</aside>`:`<p>${subject} = S − hasil tambah sudut yang diberi.</p><p>Tolak jumlah sudut yang diketahui daripada jumlah sudut pedalaman poligon.</p>`,'isolate');
