        if(external){const dx=point.x-previous.x,dy=point.y-previous.y,length=Math.hypot(dx,dy);extensions+=`<path data-mixed-angle-extension="${index}" d="M${value(point.x)} ${value(point.y)} L${value(point.x+dx/length*80)} ${value(point.y+dy/length*80)}" fill="none" stroke="#7b748c" stroke-width="2.5" stroke-dasharray="7 5"/>`;}
