          if(mode==='sides')sideMarkup+=`<path d="M${value(point.x)} ${value(point.y)} L${value(next.x)} ${value(next.y)}" stroke="${colour}" stroke-width="4"/>`;
          for(let band=0;band<bands;band++){const offset=(band-(bands-1)/2)*8,cx=middle.x+tangent.x*offset,cy=middle.y+tangent.y*offset;sideMarkup+=`<path data-side-mark="${index}" d="M${value(cx-normal.x*7)} ${value(cy-normal.y*7)} L${value(cx+normal.x*7)} ${value(cy+normal.y*7)}" stroke="${colour}" stroke-width="3" stroke-linecap="round"/>`;}
