        muffin:'<path d="M33 51 H111 L100 102 H45 Z" fill="#cdb0df" stroke="#866e98" stroke-width="2"/><path d="M25 55 C14 28 42 17 51 23 C59 1 96 6 99 24 C123 19 134 46 117 56 Z" fill="#e7b875" stroke="#9b713e" stroke-width="2"/><path d="M55 63 L59 95 M73 62 V95 M92 63 L87 95" stroke="#fff" stroke-width="3"/>',
        brownie:'<path d="M22 45 L61 20 L124 39 L88 65 Z" fill="#8e5b40" stroke="#5f402f" stroke-width="2"/><path d="M22 45 V85 L88 107 V65 M88 65 L124 39 V81 L88 107" fill="#b27854" stroke="#5f402f" stroke-width="2"/><g fill="#e5b281"><circle cx="59" cy="38" r="5"/><circle cx="88" cy="44" r="5"/><circle cx="72" cy="54" r="4"/></g>',
        tart:'<ellipse cx="73" cy="64" rx="56" ry="31" fill="#cc914b" stroke="#976735" stroke-width="2"/><ellipse cx="73" cy="54" rx="54" ry="30" fill="#f3c96b" stroke="#976735" stroke-width="2"/><ellipse cx="73" cy="52" rx="40" ry="21" fill="#fff0ac"/>',
