    function renderIndexConversionDivisionVisual(item,showAnswer,formatValue){
      const data=item?.indexConversionData;if(!data)return'';
      const row=(divisor,value,type='step',extra='')=>`<div class="index-division-row ${type}"><div class="index-division-divisor">${divisor}</div><div class="index-division-dividend ${extra}">${value}</div></div>`;
      if(!showAnswer){const rows=row(formatValue(data.baseDisplay),formatValue(data.numberDisplay))+row(formatValue(data.baseDisplay),'?','step','unknown')+row('⋮','⋮','ellipsis')+row('',formatValue('1'),'final');return`<figure class="index-division-visual hint" role="img" aria-label="Panduan tangga pembahagian berulang menggunakan asas yang diberi"><h3>Kaedah pembahagian berulang</h3><div class="index-division-bracket-layout"><div class="index-division-count"><i>n</i> = ?</div><div class="index-division-bracket hint">${rows}</div></div><figcaption>Bahagi dengan asas yang sama pada setiap baris sehingga mendapat 1. Bilangan pembahagian ialah nilai <i>n</i>.</figcaption></figure>`;}
      const rows=data.divisionChain.map((value,index)=>index<data.exponent?row(formatValue(data.baseDisplay),formatValue(value)):row('',formatValue(value),'final')).join('');
      return`<figure class="index-division-visual solution" role="img" aria-label="Tangga pembahagian berulang lengkap dengan n sama dengan ${data.exponent}"><h3>Kaedah pembahagian berulang</h3><div class="index-division-bracket-layout"><div class="index-division-count"><i>n</i> = ${data.exponent}</div><div class="index-division-bracket solution">${rows}</div></div><figcaption>Asas ${formatValue(data.baseDisplay)} digunakan sebanyak ${data.exponent} kali sebelum hasil bahagi menjadi 1.</figcaption></figure>`;
    }
    const formatQuizMathTextBeforeIndexConversionVisual=formatQuizMathText;
    formatQuizMathText=function(value,item,options={}){
      const formatValue=entry=>formatQuizMathTextBeforeIndexConversionVisual(entry,item,options);
      return formatQuizMathTextBeforeIndexConversionVisual(value,item,options).replace(/__INDEX_CONVERSION_HINT__/g,()=>renderIndexConversionDivisionVisual(item,false,formatValue)).replace(/__INDEX_CONVERSION_SOLUTION__/g,()=>renderIndexConversionDivisionVisual(item,true,formatValue));
    };
