      if(scene==='drone')return`<line class="horizontal-guide" x1="${x}" y1="${topY+18}" x2="${x}" y2="360"/><g transform="translate(${x} ${topY+12})"><rect class="target-accent" x="-24" y="-9" width="48" height="18" rx="7"/><line class="target-line" x1="-45" y1="-16" x2="45" y2="-16"/><line class="target-line" x1="-40" y1="-16" x2="-24" y2="0"/><line class="target-line" x1="40" y1="-16" x2="24" y2="0"/></g>`;
      if(scene==='lighthouse')return`<polygon class="target-fill" points="${x-42},360 ${x-22},${topY+45} ${x+22},${topY+45} ${x+42},360"/><rect class="target-accent" x="${x-29}" y="${topY+18}" width="58" height="30" rx="5"/><line class="target-line" x1="${x-36}" y1="${topY+18}" x2="${x+36}" y2="${topY+18}"/>`;
