      if(method==='form-four-cuboid-surface')return set(method,'Membina ungkapan jumlah luas permukaan kuboid.',['Kenal pasti panjang p, lebar l dan tinggi t.','Kira luas satu muka bagi setiap pasangan: pl, pt dan lt.','Jumlahkan ketiga-tiga luas dan darab dengan 2.'],['Jumlah luas permukaan = 2(pl + pt + lt)'],[sym('p','panjang kuboid'),sym('l','lebar kuboid'),sym('t','tinggi kuboid'),sym('cm²','unit luas')]);
      if(method==='form-four-quadratic-roots')return set(method,'Mencari kedua-dua punca persamaan kuadratik.',['Kembangkan kurungan di sebelah kanan.','Susun semua sebutan dalam bentuk ax² + bx + c = 0.','Faktorkan ungkapan dan tetapkan setiap faktor kepada sifar.','Semak punca dengan menggantikan nilainya ke dalam persamaan asal.'],['ax² + bx + c = 0','AB = 0 bermaksud A = 0 atau B = 0'],[sym('punca','nilai x yang memenuhi persamaan'),sym('pintasan-x','titik pada graf apabila y = 0')]);
      if(method==='form-four-quadratic-fact')return set('form-four-quadratic-fact','Mengenal pasti satu pernyataan yang tidak betul tentang fungsi kuadratik dengan domain semua nombor nyata.',['Kenal pasti bentuk fungsi dan pastikan pekali x² bukan sifar.','Semak tanda pekali x² untuk menentukan sama ada fungsi mempunyai nilai maksimum atau minimum.','Uji setiap pernyataan menggunakan sifat parabola, paksi simetri atau penggantian nilai x.','Pilih hanya pernyataan yang tidak betul; jangan pilih pernyataan yang benar.'],['f(x) = ax² + bx + c, dengan a ≠ 0','a > 0: nilai minimum; a < 0: nilai maksimum','f(x) = a(x − h)² + k: titik puncak (h, k) dan paksi simetri x = h'],[sym('x','input daripada semua nombor nyata'),sym('f(x)','output atau nilai fungsi'),sym('a','pekali x² yang menentukan arah bukaan parabola'),sym('b, c','pekali x dan sebutan pemalar dalam bentuk am'),sym('h, k','koordinat titik puncak dalam bentuk a(x − h)² + k')]);
      if(method==='form-four-quadratic-expression')return set('form-four-quadratic-expression','Mengenal pasti ungkapan kuadratik dalam satu pemboleh ubah selepas ungkapan dipermudahkan.',['Kembangkan kurungan dan kumpulkan sebutan serupa terlebih dahulu.','Pastikan ungkapan ialah polinomial dalam satu pemboleh ubah sahaja.','Semak bahawa kuasa tertinggi selepas pemudahan ialah 2 dan pekali kuasa dua bukan sifar.','Bezakan penyebut nombor tetap daripada penyebut yang masih mengandungi pemboleh ubah selepas pemudahan.'],['au² + bu + c, dengan a ≠ 0','Darjah ungkapan kuadratik = 2','b dan c boleh bernilai sifar; a tidak boleh bernilai sifar'],[sym('u','satu-satunya pemboleh ubah dalam bentuk am'),sym('a, b, c','pemalar nyata; a ialah pekali u²'),sym('darjah','kuasa tertinggi pemboleh ubah selepas pemudahan')]);
      if(method==='form-four-quadratic-minimum')return set('form-four-quadratic-minimum','Memilih fungsi kuadratik yang mempunyai titik minimum.',['Susun atau kembangkan setiap fungsi kepada bentuk y = ax² + bx + c.','Kenal pasti pekali x², termasuk tandanya.','Jika a > 0, parabola membuka ke atas dan mempunyai titik minimum. Jika a < 0, parabola membuka ke bawah dan mempunyai titik maksimum.','Pilih fungsi yang pekali x²-nya positif; tanda b dan c tidak menentukan jenis titik puncak.'],['y = ax² + bx + c, dengan a ≠ 0','a > 0: titik minimum','a < 0: titik maksimum'],[sym('a','pekali x² selepas fungsi dipermudahkan'),sym('b','pekali x'),sym('c','sebutan pemalar'),sym('titik minimum','titik paling rendah pada parabola yang membuka ke atas')]);
