      if(method==='significant-figures-count')return set('significant-figures',objective,['Abaikan tanda negatif dan unit kerana kedua-duanya bukan digit.','Cari digit bukan sifar pertama; semua sifar di sebelah kirinya tidak dikira.','Kira semua digit bukan sifar dan sifar yang berada di antara digit bukan sifar.','Bagi nombor perpuluhan, kira sifar di hujung selepas digit bukan sifar.','Bagi nombor bulat, gunakan tahap kejituan yang dinyatakan untuk menentukan digit terakhir yang dikira.','Dalam bentuk piawai, kira digit pada pekali sahaja.'],['Angka bererti bermula pada digit bukan sifar pertama','Sifar di antara digit bukan sifar ialah angka bererti','Sifar di hujung nombor perpuluhan ialah angka bererti','Kuasa 10 tidak mengubah bilangan angka bererti'],[sym('Digit bukan sifar pertama','digit permulaan bagi kiraan angka bererti'),sym('Sifar pendahulu','sifar sebelum digit bukan sifar pertama; tidak dikira'),sym('Tahap kejituan','nilai tempat terakhir yang dianggap tepat'),sym('A × 10ⁿ','bentuk piawai; bilangan angka bererti ditentukan oleh A')]);
      if(method==='significant-figures-rounding')return set('significant-figures-rounding',objective,['Cari digit bukan sifar pertama; digit itu ialah angka bererti pertama.','Kira dan tandakan tiga angka bererti yang pertama.','Periksa digit sejurus selepas angka bererti ketiga; digit itu ialah digit pembundaran.','Jika digit pembundaran kurang daripada 5, kekalkan angka bererti ketiga. Jika digit itu 5 atau lebih, tambah 1.','Bagi nombor bulat, tukar baki digit kepada sifar. Bagi nombor perpuluhan, gugurkan baki digit dan kekalkan sifar hujung yang diperlukan.'],['Digit pembundaran < 5 → kekalkan angka bererti ketiga','Digit pembundaran ≥ 5 → tambah 1 pada angka bererti ketiga','Jawapan mesti menunjukkan tepat 3 a.b.'],[sym('a.b.','angka bererti'),sym('Digit pembundaran','digit sejurus selepas angka bererti terakhir yang hendak dikekalkan'),sym('3 a.b.','tiga angka bererti pada jawapan akhir')]);
      if(method==='significant-figures-paired-rounding'){const target=item?.significantRoundingPairData?.target||'sasaran';return set('significant-figures-paired-rounding',objective,[`Bagi setiap nombor, cari digit bukan sifar pertama dan tandakan ${target} angka bererti.`,`Periksa digit sejurus selepas angka bererti ke-${target}.`,'Kekalkan digit terakhir jika digit pembundaran kurang daripada 5; tambah 1 jika digit itu 5 atau lebih.','Tukar baki tempat nombor bulat kepada sifar atau gugurkan baki digit perpuluhan.','Tambah sifar di hujung perpuluhan jika perlu untuk menunjukkan bilangan angka bererti yang diminta.'],['Digit selepas sasaran < 5 → kekalkan digit terakhir','Digit selepas sasaran ≥ 5 → tambah 1 pada digit terakhir',`Kedua-dua jawapan mesti mempunyai ${target} a.b.`],[sym('a.b.','angka bererti'),sym(String(target),`bilangan angka bererti yang diminta bagi kedua-dua nombor`),sym('Digit pembundaran','digit sejurus selepas angka bererti terakhir yang dikekalkan')]);}
