      if(method==='standard-form-multiply-divide')return set('standard-form-multiply-divide',objective,['Asingkan operasi pekali daripada operasi kuasa 10.','Bagi pendaraban, darabkan pekali dan tambahkan indeks.','Bagi pembahagian, gunakan pecahan bertingkat berkurungan: hitung pecahan pekali dan tolak indeks penyebut daripada indeks pengangka.','Gabungkan hasil pekali dengan kuasa 10.','Jika pekali bukan dalam julat 1 ≤ A < 10, ubah pekali dan laraskan indeks.'],['(a × 10ᵐ)(b × 10ⁿ) = (a × b) × 10ᵐ⁺ⁿ',`(${f('a × 10ᵐ','b × 10ⁿ')}) = (${f('a','b')}) × 10ᵐ⁻ⁿ`,'1 ≤ A < 10'],[sym('a, b','pekali nombor dalam bentuk piawai'),sym('m, n','indeks kuasa 10'),sym('m + n','indeks hasil pendaraban'),sym('m − n','indeks hasil pecahan'),sym('A','pekali jawapan akhir')]);
      if(method==='standard-form-story-application'){const operation=item?.standardStoryData?.operation,formula=operation==='divide'?`Kuantiti seunit = (${f('jumlah kuantiti','bilangan unit')})`:operation==='multiply'?'Jumlah = bilangan unit × kuantiti seunit':'Baki atau beza = jumlah asal − jumlah digunakan';return set('standard-form-story-application',objective,['Kenal pasti kuantiti yang diberi, kuantiti yang diminta dan unit jawapan.','Tulis hubungan harian sebagai formula perkataan sebelum menggantikan nombor.','Tukarkan semua nombor kepada bentuk piawai yang serasi.','Gunakan hukum indeks yang sesuai untuk operasi tambah, tolak, darab atau pecahan.','Semak pekali akhir dan sertakan unit atau mata wang dalam jawapan.'],[formula,'Tambah/tolak: samakan indeks dahulu','Darab: tambah indeks','Pecahan: tolak indeks penyebut daripada indeks pengangka','1 ≤ A < 10'],[sym('Jumlah','kuantiti keseluruhan dalam situasi'),sym('Baki atau beza','jumlah asal selepas kuantiti yang digunakan atau kos ditolak'),sym('Kuantiti seunit','jumlah bagi setiap satu unit, bekas atau penerima'),sym('A','pekali jawapan bentuk piawai')]);}
