      if(method==='simple-interest-two-period-total-story')return set('simple-interest-two-period-total-story',objective,['Kenal pasti prinsipal P dan kadar faedah mudah tahunan r yang digunakan untuk kedua-dua tempoh.','Tukar kadar peratus kepada perpuluhan menggunakan pecahan bertingkat berkurungan.','Tentukan t₁ bagi bahagian (a) dan t₂ bagi bahagian (b); tukar bulan kepada tahun menggunakan pecahan bertingkat jika perlu.','Kira faedah mudah berasingan bagi setiap tempoh menggunakan I = P × r × t.','Tambah setiap faedah kepada prinsipal yang sama menggunakan A = P + I.','Nyatakan kedua-dua jumlah simpanan mengikut label (a) dan (b).'],['I = P × r × t','A = P + I',`r = (${f('kadar peratus','100')})`,`t = (${f('bilangan bulan','12 bulan')}) (jika tempoh diberi dalam bulan)`],[sym('I','faedah mudah bagi tempoh yang sedang dihitung'),sym('A','jumlah simpanan akhir bagi sesuatu tempoh'),sym('P','prinsipal atau simpanan asal yang sama bagi kedua-dua bahagian'),sym('r','kadar faedah tahunan dalam bentuk perpuluhan'),sym('t₁','tempoh simpanan bagi bahagian (a), dalam tahun'),sym('t₂','tempoh simpanan bagi bahagian (b), dalam tahun'),sym('RM','Ringgit Malaysia')]);
      if(method==='simple-interest-comparison-story')return set('simple-interest-comparison-story',objective,['Kenal pasti prinsipal P dan tempoh t yang sama bagi kedua-dua pilihan simpanan.','Tukar setiap kadar peratus kepada perpuluhan menggunakan pecahan bertingkat berkurungan.','Kira faedah mudah bagi pilihan pertama dan pilihan kedua secara berasingan menggunakan I = P × r × t.','Tambah faedah kepada prinsipal untuk menyemak jumlah wang simpanan setiap pilihan.','Bagi bahagian (a), pilih institusi yang memberikan faedah atau jumlah simpanan lebih tinggi.','Bagi bahagian (b), tolak faedah yang lebih rendah daripada faedah yang lebih tinggi.'],['I = P × r × t','A = P + I',`r = (${f('kadar peratus','100')})`,`t = (${f('bilangan bulan','12 bulan')}) (jika tempoh diberi dalam bulan)`,'Beza faedah = faedah lebih tinggi − faedah lebih rendah'],[sym('I','faedah mudah bagi sesuatu pilihan simpanan'),sym('A','jumlah wang simpanan selepas faedah ditambah'),sym('P','prinsipal yang sama bagi kedua-dua pilihan'),sym('r','kadar faedah tahunan bagi setiap pilihan dalam bentuk perpuluhan'),sym('t','tempoh simpanan yang sama bagi kedua-dua pilihan, dalam tahun'),sym('RM','Ringgit Malaysia')]);
      if(method==='hibah-rate-from-saving-story')return set('hibah-rate-from-saving-story',objective,['Baca jadual dan kenal pasti jumlah simpanan, tempoh serta jumlah hibah yang diterima.','Letakkan jumlah hibah sebagai pengangka dan jumlah simpanan sebagai penyebut.','Gunakan pecahan bertingkat berkurungan supaya operasi pembahagian jelas.','Darabkan nilai pecahan dengan 100% untuk menukarkannya kepada peratus.','Tempoh simpanan menerangkan tempoh hibah itu diterima; jangan darab atau bahagi dengan tempoh apabila soalan hanya meminta peratus hibah bagi tempoh tersebut.','Semak bahawa jawapan akhir mempunyai tanda peratus.'],[`Peratus hibah = (${f('jumlah hibah','jumlah simpanan')}) × 100%`],[sym('Jumlah hibah','wang tambahan yang diberikan berdasarkan simpanan'),sym('Jumlah simpanan','wang asal yang menjadi asas pengiraan hibah'),sym('100%','faktor untuk menukarkan nisbah kepada peratus'),sym('RM','Ringgit Malaysia')]);
      if(method==='unit-trust-dividend-bonus-return-story')return set('unit-trust-dividend-bonus-return-story',objective,['Kenal pasti bilangan unit, harga seunit, kadar dividen dan kadar bonus istimewa daripada cerita.','Darabkan bilangan unit dengan harga seunit untuk mendapatkan nilai pelaburan.','Tukar kadar dividen kepada perpuluhan menggunakan pecahan bertingkat berkurungan, kemudian darab dengan nilai pelaburan.','Ulang langkah yang sama bagi kadar bonus istimewa.','Tambah jumlah dividen dan bonus istimewa untuk mendapatkan jumlah pulangan.','Nyatakan jawapan akhir dalam Ringgit Malaysia dan jangan campurkan modal asal kerana soalan hanya meminta pulangan.'],['Nilai pelaburan = bilangan unit × harga seunit',`Dividen = (${f('kadar dividen','100')}) × nilai pelaburan`,`Bonus istimewa = (${f('kadar bonus','100')}) × nilai pelaburan`,'Jumlah pulangan = dividen + bonus istimewa'],[sym('Bilangan unit','jumlah unit amanah saham atau pelaburan yang dimiliki'),sym('Harga seunit','nilai wang bagi setiap satu unit'),sym('Kadar dividen','peratus dividen yang dibayar atas nilai pelaburan'),sym('Kadar bonus','peratus bonus istimewa yang dibayar atas nilai pelaburan'),sym('RM','Ringgit Malaysia')]);
      if(method==='share-dividend-roi-story')return set('share-dividend-roi-story',objective,['Kenal pasti bilangan unit saham, harga belian seunit, harga jualan seunit dan kadar dividen daripada cerita.','Cari nilai pelaburan awal dengan mendarab bilangan unit dengan harga belian seunit.','Bagi bahagian (a), tukar kadar dividen kepada perpuluhan menggunakan pecahan bertingkat berkurungan, kemudian darab dengan nilai pelaburan awal.','Cari peningkatan harga seunit dengan menolak harga belian daripada harga jualan. Darabkan peningkatan itu dengan bilangan unit untuk memperoleh keuntungan modal.','Tambah dividen dan keuntungan modal untuk mendapatkan jumlah pulangan.','Bagi bahagian (b), letakkan jumlah pulangan sebagai pengangka dan nilai pelaburan awal sebagai penyebut, kemudian darab dengan 100%.','Nyatakan bahagian (a) dalam Ringgit Malaysia dan bahagian (b) sebagai peratus.'],['Nilai pelaburan awal = bilangan unit × harga belian seunit',`Dividen = (${f('kadar dividen','100')}) × nilai pelaburan awal`,'Peningkatan harga seunit = harga jualan − harga belian','Keuntungan modal = bilangan unit × peningkatan harga seunit','Jumlah pulangan = dividen + keuntungan modal',`ROI = (${f('jumlah pulangan','nilai pelaburan awal')}) × 100%`],[sym('ROI','nilai pulangan pelaburan, dinyatakan sebagai peratus daripada modal awal'),sym('Bilangan unit','jumlah saham yang dibeli dan dijual'),sym('Harga belian','harga asal bagi setiap unit saham'),sym('Harga jualan','harga bagi setiap unit ketika saham dijual'),sym('Dividen','agihan pendapatan berdasarkan nilai pelaburan awal'),sym('Keuntungan modal','keuntungan akibat kenaikan harga saham'),sym('RM','Ringgit Malaysia')]);
      if(method==='property-capital-gain-roi-story')return set('property-capital-gain-roi-story',objective,['Baca cerita dan jadual untuk mengenal pasti harga belian, bayaran pendahuluan, baki pinjaman, ansuran yang telah dibayar, harga jualan serta semua kos urusan.','Jumlahkan kos guaman, duti setem, komisen ejen dan apa-apa kos lain yang disenaraikan dalam jadual.','Bagi bahagian (a), tolak bayaran pendahuluan, baki pinjaman, ansuran dibayar dan jumlah perbelanjaan daripada harga jualan untuk mendapatkan keuntungan modal.','Kira sewa terkumpul dengan mendarab bilangan bulan sewaan dengan kadar sewa bulanan.','Tambah sewa terkumpul kepada keuntungan modal untuk memperoleh jumlah pulangan pelaburan.','Bagi bahagian (b), letakkan jumlah pulangan sebagai pengangka dan nilai belian hartanah sebagai penyebut, kemudian darabkan dengan 100%.','Nyatakan keuntungan modal dalam RM dan ROI sebagai peratus.'],['Jumlah perbelanjaan = kos guaman + duti setem + komisen ejen','Keuntungan modal = harga jualan − bayaran pendahuluan − baki pinjaman − ansuran dibayar − jumlah perbelanjaan','Sewa terkumpul = bilangan bulan × sewa bulanan','Jumlah pulangan = sewa terkumpul + keuntungan modal',`ROI = (${f('jumlah pulangan','nilai belian hartanah')}) × 100%`],[sym('ROI','nilai pulangan pelaburan hartanah sebagai peratus daripada harga belian'),sym('Keuntungan modal','baki hasil jualan selepas semua bayaran dan kos yang dinyatakan ditolak'),sym('Sewa terkumpul','jumlah sewa yang diterima sepanjang tempoh sewaan'),sym('Jumlah pulangan','keuntungan modal ditambah sewa terkumpul'),sym('RM','Ringgit Malaysia')]);
      if(method==='lump-sum-vs-periodic-investment-story')return set('lump-sum-vs-periodic-investment-story',objective,['Kenal pasti jumlah modal yang sama bagi kedua-dua pelabur, harga belian pelabur sekali gus, jumlah pelaburan setiap tempoh dan harga seunit bagi setiap tempoh.','Gunakan pecahan bertingkat berkurungan untuk mencari bilangan unit: jumlah pelaburan sebagai pengangka dan harga seunit sebagai penyebut.','Bagi pelabur sekali gus, hitung unit sekali sahaja. Kos purata seunitnya sama dengan harga belian awal.','Bagi pelabur berkala, hitung unit bagi setiap tempoh secara berasingan dan ambil bilangan unit bulat seperti dalam contoh.','Jumlahkan semua unit pelabur berkala, kemudian bahagikan jumlah modal dengan jumlah unit menggunakan pecahan berkurungan untuk mencari kos purata seunit.','Bagi bahagian (b), bandingkan jumlah unit dan kos purata seunit. Pelabur yang mempunyai lebih banyak unit pada kos purata lebih rendah ialah pilihan yang lebih baik untuk siri harga tersebut.'],[`Bilangan unit = (${f('jumlah pelaburan','harga seunit')})`,`Kos purata seunit = (${f('jumlah pelaburan keseluruhan','jumlah unit')})`,'Pelaburan berkala = jumlah unit setiap tempoh','Strategi lebih baik → lebih banyak unit dan kos purata lebih rendah'],[sym('Jumlah pelaburan','wang yang dilaburkan sekali gus atau sepanjang semua tempoh'),sym('Harga seunit','harga satu unit saham atau dana pada tempoh pembelian'),sym('Bilangan unit','bilangan unit bulat yang diperoleh daripada sesuatu pembelian'),sym('Kos purata seunit','jumlah modal dibahagikan kepada jumlah unit yang dimiliki'),sym('RM','Ringgit Malaysia')]);
      if(method==='financed-property-resale-roi-story')return set('financed-property-resale-roi-story',objective,['Kenal pasti harga belian asal, harga jualan dan semua bayaran sepanjang tempoh pemilikan daripada cerita serta jadual.','Jumlahkan ansuran pinjaman, duti setem, komisen ejen dan setiap perbelanjaan lain yang disenaraikan.','Tolak jumlah perbelanjaan daripada harga jualan untuk mendapatkan keuntungan jualan hartanah.','Letakkan keuntungan jualan sebagai pengangka dan harga belian asal sebagai penyebut dalam pecahan berkurungan.','Darabkan nilai pecahan dengan 100% untuk mendapatkan nilai pulangan pelaburan.','Bulatkan jawapan kepada dua tempat perpuluhan apabila perlu dan sertakan tanda peratus.'],['Jumlah perbelanjaan = ansuran pinjaman + duti setem + komisen ejen + perbelanjaan lain','Keuntungan jualan = harga jualan − jumlah perbelanjaan',`ROI = (${f('keuntungan jualan','harga belian asal')}) × 100%`],[sym('ROI','nilai pulangan pelaburan hartanah sebagai peratus daripada harga belian asal'),sym('Keuntungan jualan','lebihan harga jualan selepas semua bayaran yang dinyatakan ditolak'),sym('Harga belian','harga asal hartanah yang menjadi asas pengiraan ROI'),sym('Jumlah perbelanjaan','jumlah ansuran pinjaman dan semua kos lain dalam jadual'),sym('RM','Ringgit Malaysia'),sym('100%','faktor untuk menukarkan nisbah kepada peratus')]);
      if(method==='credit-card-concept-effect-story'){
        const calculation=Boolean(item?.creditCardData?.calculation),formulas=calculation?[`Bayaran minimum = (${f('kadar minimum','100')}) × baki akhir penyata`,'Baki selepas bayaran = baki akhir penyata − bayaran minimum','Baki seterusnya = baki tertunggak + caj kewangan + caj lewat − bayaran tambahan']:['Kad kredit = kemudahan beli sekarang dan bayar kemudian kepada pengeluar kad','Penggunaan bijak = berbelanja mengikut kemampuan + bayar penuh tepat pada masa','Bayaran minimum atau lewat → baki tertunggak dan caj boleh meningkat'];
        return set('credit-card-concept-effect-story',objective,['Kenal pasti sama ada soalan meminta maksud, kelebihan, kekurangan atau kesan sesuatu cara pembayaran kad kredit.','Bezakan kad kredit daripada kad debit: kad kredit menggunakan had yang diberikan oleh pengeluar kad dan perlu dibayar kemudian.','Semak setiap pernyataan berdasarkan kemampuan berbelanja, tarikh akhir bayaran, baki tertunggak dan caj yang mungkin dikenakan.','Jika kadar bayaran minimum diberi, gunakan pecahan berkurungan kadar minimum di atas 100 dan darab dengan baki penyata.','Ingat bahawa bayaran minimum tidak bermaksud hutang selesai; baki yang belum dibayar boleh dikenakan caj kewangan.','Pembayaran lewat pula boleh menyebabkan caj lewat, caj kewangan dan rekod kredit terjejas.'],formulas,[sym('Kad kredit','kemudahan kredit yang membolehkan pemegang kad membuat bayaran dahulu melalui pengeluar kad dan menjelaskan hutang kemudian'),sym('Baki penyata','jumlah yang tertera pada penyata kad kredit bagi sesuatu kitaran'),sym('Bayaran minimum','jumlah paling rendah yang perlu dibayar; bukan bayaran penuh'),sym('Caj kewangan','faedah atau caj atas baki yang tidak dibayar penuh'),sym('Tarikh akhir','tarikh pembayaran perlu diterima untuk mengelakkan kelewatan'),sym('RM','Ringgit Malaysia')]);
      }
      if(method==='credit-card-minimum-payment-story')return set('credit-card-minimum-payment-story',objective,['Baca jadual dan kenal pasti jumlah terkini bagi setiap kad kredit atau tempoh penyata.','Cari 5% daripada setiap jumlah terkini menggunakan pecahan bertingkat yang diletakkan dalam kurungan.','Bandingkan nilai 5% itu dengan RM50 bagi setiap kad secara berasingan.','Jika 5% melebihi RM50, gunakan nilai 5%. Jika 5% kurang daripada RM50, gunakan RM50.','Jika kedua-duanya sama, bayaran minimum tetap RM50.','Nyatakan bayaran minimum bagi setiap kad mengikut label dalam soalan.'],[`Nilai 5% = (${f('5','100')}) × jumlah terkini`,'Bayaran minimum = nilai yang lebih tinggi antara 5% jumlah terkini dan RM50','Jika nilai 5% < RM50 → bayaran minimum RM50','Jika nilai 5% ≥ RM50 → bayaran minimum ialah nilai 5%'],[sym('5%','kadar bayaran minimum berdasarkan jumlah terkini'),sym('Jumlah terkini','baki yang tertera pada penyata kad kredit'),sym('RM50','nilai minimum tetap yang perlu dibandingkan dengan 5%'),sym('Bayaran minimum','jumlah paling rendah yang perlu dibayar bagi kad tersebut'),sym('RM','Ringgit Malaysia')]);
      if(method==='credit-card-statement-three-part-story')return set('credit-card-statement-three-part-story',objective,['Kenal pasti jumlah terkini, kadar faedah tahunan, caj bayaran lewat dan bilangan hari daripada jadual.','Bagi bahagian (a), cari 5% daripada jumlah terkini dan bandingkan dengan RM50 untuk mendapatkan bayaran minimum.','Bagi bahagian (b), tolak bayaran minimum daripada jumlah terkini untuk mendapatkan baki belum dijelaskan.','Kira caj kewangan atas baki belum dijelaskan menggunakan kadar tahunan dan pecahan bilangan hari di atas 365 hari.','Tambah caj kewangan kepada baki belum dijelaskan untuk memperoleh baki penyata berikutnya bagi bahagian (b).','Bagi bahagian (c), gunakan jumlah terkini asal kerana tiada bayaran dibuat; hitung caj kewangan dan caj lewat 1%, kemudian tambahkan semuanya.'],[`Bayaran minimum = nilai lebih tinggi antara (${f('5','100')}) × jumlah terkini dan RM50`,'Baki belum dijelaskan = jumlah terkini − bayaran minimum',`Caj kewangan = baki × [(${f('kadar tahunan','100')}) × (${f('bilangan hari','365')})]`,`Caj lewat = (${f('kadar lewat','100')}) × jumlah terkini`,'Baki baharu jika bayar minimum = baki belum dijelaskan + caj kewangan','Baki baharu jika tiada bayaran = jumlah terkini + caj kewangan + caj lewat'],[sym('Jumlah terkini','baki tertunggak pada penyata semasa'),sym('Bayaran minimum','jumlah paling rendah yang perlu dibayar dalam tempoh ditetapkan'),sym('Baki belum dijelaskan','jumlah terkini selepas bayaran minimum ditolak'),sym('Caj kewangan','faedah mengikut kadar tahunan dan bilangan hari'),sym('Caj lewat','caj tambahan apabila pembayaran tidak dibuat pada waktunya'),sym('365','bilangan hari yang digunakan sebagai asas setahun'),sym('RM','Ringgit Malaysia')]);
      if(method==='credit-card-overseas-purchase-comparison-story')return set('credit-card-overseas-purchase-comparison-story',objective,['Kenal pasti harga promosi, caj penghantaran, kadar pertukaran, caj bank dan harga tawaran tempatan.','Tukar setiap nilai mata wang asing kepada Ringgit Malaysia menggunakan pecahan bertingkat berkurungan.','Kira caj tambahan bank berdasarkan harga barang luar negara yang telah ditukar kepada RM.','Tambah harga barang, penghantaran dan caj bank untuk mendapatkan harga sebenar tawaran luar negara.','Tambah harga barang dan penghantaran tempatan jika penghantaran tidak percuma.','Bandingkan kedua-dua harga sebenar, pilih jumlah yang lebih rendah dan nyatakan penjimatan sebagai justifikasi.'],[`Harga asing dalam RM = (${f('harga dalam mata wang asing','unit mata wang asing bagi RM1')})`,`Penghantaran dalam RM = (${f('caj penghantaran asing','unit mata wang asing bagi RM1')})`,`Caj bank = (${f('kadar caj bank','100')}) × harga barang asing dalam RM`,'Harga sebenar luar negara = harga barang RM + penghantaran RM + caj bank','Harga sebenar tempatan = harga promosi tempatan + penghantaran tempatan','Penjimatan = harga lebih tinggi − harga lebih rendah'],[sym('RM','Ringgit Malaysia'),sym('Kadar pertukaran','bilangan unit mata wang asing yang bersamaan RM1'),sym('Caj bank','caj tambahan bagi transaksi luar negara'),sym('Harga sebenar','jumlah yang dibayar selepas semua caj ditambah'),sym('Penjimatan','beza antara tawaran lebih mahal dengan tawaran pilihan')]);
      if(method==='flat-rate-credit-purchase-story')return set('flat-rate-credit-purchase-story',objective,['Kenal pasti harga belian, peratus bayaran pendahuluan, kadar faedah sama rata dan tempoh kredit.','Kira bayaran pendahuluan menggunakan pecahan kadar pendahuluan di atas 100.','Tolak bayaran pendahuluan daripada harga belian untuk mendapatkan jumlah pinjaman P.','Kira faedah sama rata menggunakan I = P × r × t.','Tambah jumlah pinjaman dan faedah untuk mendapatkan jumlah bayaran balik A.','Tukar tempoh tahun kepada bulan, kemudian bahagi jumlah bayaran balik menggunakan pecahan bertingkat berkurungan untuk mendapatkan ansuran bulanan.'],[`Bayaran pendahuluan = (${f('kadar pendahuluan','100')}) × harga belian`,'P = harga belian − bayaran pendahuluan','I = P × r × t','A = P + I = P + Prt',`Ansuran bulanan = (${f('A','t × 12')})`],[sym('P','jumlah pinjaman selepas bayaran pendahuluan ditolak'),sym('I','jumlah faedah sama rata sepanjang tempoh kredit'),sym('r','kadar faedah tahunan dalam bentuk perpuluhan'),sym('t','tempoh kredit dalam tahun'),sym('A','jumlah bayaran balik, iaitu pinjaman ditambah faedah'),sym('12','bilangan bulan dalam setahun'),sym('RM','Ringgit Malaysia')]);
      if(method==='personal-loan-flat-rate-story')return set('personal-loan-flat-rate-story',objective,['Kenal pasti prinsipal pinjaman P, kadar faedah sama rata r dan tempoh bayaran balik t.','Tukar kadar peratus kepada perpuluhan menggunakan pecahan berpenyebut 100.','Kira faedah sama rata menggunakan I = P × r × t.','Tambah faedah kepada prinsipal untuk mendapatkan jumlah bayaran balik A.','Tukar tempoh tahun kepada bulan dengan mendarab t × 12.','Cari ansuran bulanan menggunakan pecahan bertingkat berkurungan dan bundarkan kepada dua tempat perpuluhan jika perlu.'],[`r = (${f('kadar peratus','100')})`,'I = P × r × t','A = P + Prt',`Bilangan bulan = t × 12`,`Ansuran bulanan = (${f('A','t × 12')})`],[sym('P','prinsipal atau jumlah pinjaman peribadi'),sym('I','jumlah faedah sama rata sepanjang tempoh pinjaman'),sym('r','kadar faedah tahunan dalam bentuk perpuluhan'),sym('t','tempoh bayaran balik dalam tahun'),sym('A','jumlah bayaran balik, iaitu prinsipal ditambah faedah'),sym('12','bilangan bulan dalam setahun'),sym('RM','Ringgit Malaysia')]);
      if(method==='reducing-balance-loan-interest-story')return set('reducing-balance-loan-interest-story',objective,['Kenal pasti baki hutang awal, kadar faedah tahunan, ansuran bulanan dan bilangan bulan yang diminta.','Bagi setiap bulan, kira faedah atas baki hutang pada awal bulan sahaja.','Gunakan pecahan satu di atas 12 untuk menukar kadar tahunan kepada kadar sebulan.','Tambah faedah bulan semasa kepada baki awal, kemudian tolak ansuran bulanan untuk mendapatkan baki bulan seterusnya.','Gunakan baki baharu sebagai baki awal bagi bulan berikutnya dan ulang langkah tanpa kembali kepada prinsipal asal.','Tambah semua faedah bulanan dalam tempoh yang diminta dan bundarkan wang kepada dua tempat perpuluhan.'],[`Faedah bulan semasa = baki awal × (${f('kadar faedah','100')}) × (${f('1','12')})`,'Baki bulan seterusnya = baki awal + faedah − ansuran bulanan','Baki awal bulan berikutnya = baki akhir bulan semasa','Jumlah faedah = faedah bulan 1 + faedah bulan 2 + …'],[sym('Baki awal','hutang tertunggak sebelum faedah bulan semasa dikenakan'),sym('Faedah','caj bulan semasa yang dikira atas baki awal'),sym('Ansuran bulanan','bayaran tetap yang ditolak selepas faedah ditambah'),sym('1/12','satu bulan sebagai pecahan daripada setahun'),sym('RM','Ringgit Malaysia')]);
      if(method==='scale-drawing-proportionality-check')return set('scale-drawing-proportionality-check',objective,['Kenal pasti dua rajah dan padankan setiap sisi yang sepadan mengikut susunan bucu.','Bagi setiap pasangan, letakkan ukuran lukisan sebagai pengangka dan ukuran objek sebagai penyebut.','Gunakan pecahan bertingkat berkurungan untuk mengira skala setiap pasangan sisi.','Bandingkan semua nilai skala, bukan satu pasangan sisi sahaja.','Jawab Ya hanya jika semua sisi sepadan mempunyai skala yang sama; jika sekurang-kurangnya satu berbeza, jawab Tidak.','Berikan sebab dengan menyatakan sama ada semua nisbah ukuran adalah berkadaran.'],[`Skala = (${f('ukuran lukisan berskala','ukuran objek')})`,`Sisi sepadan berkadaran: (${f('sisi lukisan pertama','sisi objek pertama')}) = (${f('sisi lukisan kedua','sisi objek kedua')})`,'Semua skala sama → Ya','Sekurang-kurangnya satu skala berbeza → Tidak'],[sym('Skala','nisbah tetap antara ukuran lukisan dengan ukuran objek'),sym('Sisi sepadan','sisi pada kedudukan yang sama dalam dua rajah'),sym('Ya','semua nisbah sisi sepadan adalah sama'),sym('Tidak','sekurang-kurangnya satu nisbah sisi sepadan tidak sama')]);
      if(method==='scale-drawing-meaning-statement-choice')return set('scale-drawing-meaning-statement-choice',objective,['Baca skala a : b dari kiri ke kanan.','Nombor a menerangkan ukuran pada lukisan, model, peta atau rajah.','Nombor b menerangkan ukuran pada objek atau keadaan sebenar dalam unit yang sama.','Jika a lebih kecil daripada b, lukisan ialah pengecilan; jika a lebih besar daripada b, lukisan ialah pembesaran.','Gunakan pecahan bertingkat berkurungan untuk mencari faktor saiz.','Tukar unit hanya selepas maksud skala dalam unit yang sama dikenal pasti.','Pilih satu pernyataan yang menyatakan arah perwakilan, unit dan faktor saiz dengan betul.'],[`Skala = (${f('ukuran lukisan atau model','ukuran objek sebenar')})`,`Faktor pengecilan = (${f('b','a')}) apabila a < b`,`Faktor pembesaran = (${f('a','b')}) apabila a > b`,'a unit pada lukisan mewakili b unit pada objek sebenar'],[sym('a','nombor di sebelah kiri; ukuran lukisan, model, peta atau rajah'),sym('b','nombor di sebelah kanan; ukuran objek atau keadaan sebenar'),sym('1 : n','1 unit pada lukisan mewakili n unit sebenar'),sym('n : 1','n unit pada lukisan mewakili 1 unit sebenar; lukisan ialah pembesaran')]);
      if(method==='scale-drawing-fractional-enlargement-choice')return set('scale-drawing-fractional-enlargement-choice',objective,['Baca skala satu kepada satu per n dari kiri ke kanan.','Nilai 1 di sebelah kiri ialah 1 unit pada lukisan.','Pecahan satu per n di sebelah kanan ialah ukuran pada objek sebenar dalam unit yang sama.','Oleh sebab 1 unit lukisan mewakili kurang daripada 1 unit sebenar, lukisan ialah pembesaran.','Gunakan pecahan bertingkat berkurungan untuk membandingkan saiz lukisan dengan saiz sebenar.','Faktor pembesaran ialah n, bukannya satu per n.','Pilih pernyataan yang mengekalkan arah lukisan kepada objek sebenar dan menyatakan faktor pembesaran dengan betul.'],[`Skala = 1 : (${f('1','n')})`,`1 unit lukisan mewakili (${f('1','n')}) unit sebenar`,`Faktor pembesaran = (${f('1','satu per n')}) = n`],[sym('n','penyebut pecahan dan faktor pembesaran'),sym('1 unit lukisan','ukuran penuh pada lukisan yang diperbesar'),sym('satu per n unit sebenar','pecahan unit objek sebenar yang diwakili'),sym('Pembesaran','lukisan lebih besar daripada objek sebenar')]);
      if(method==='scale-drawing-find-scale-choice')return set('scale-drawing-find-scale-choice',objective,['Kenal pasti rajah objek dan rajah lukisan berskala.','Pilih satu pasangan sisi atau jarak yang sepadan.','Letakkan panjang sisi lukisan sebagai pengangka dan panjang sisi objek sebagai penyebut.','Ringkaskan nisbah ukuran dengan unit yang sama.','Jika sebutan pertama belum 1, gunakan pecahan bertingkat berkurungan untuk membahagikan kedua-dua sebutan dengan nilai yang sama.','Tulis jawapan akhir dalam bentuk 1 : n.','Tentukan sama ada lukisan ialah pengecilan atau pembesaran berdasarkan nilai n.'],[`Skala = (${f('panjang sisi lukisan berskala','panjang sisi objek')})`,`Skala pengecilan = 1 : n, dengan n > 1`,`Skala pembesaran = 1 : (${f('1','n')}), dengan n > 1`,`a : b = (${f('a','a')}) : (${f('b','a')}) = 1 : (${f('b','a')})`],[sym('Objek','bentuk atau ukuran sebenar yang diwakili'),sym('Lukisan berskala','rajah yang dikecilkan atau dibesarkan secara berkadaran'),sym('Sisi sepadan','dua sisi pada kedudukan yang sama dalam objek dan lukisan'),sym('n','faktor pengecilan atau penyebut faktor pembesaran')]);
      if(method==='scale-drawing-actual-length-two-scales')return set('scale-drawing-actual-length-two-scales',objective,['Kenal pasti sisi pada lukisan berskala dan sisi sebenar yang sepadan.','Baca setiap skala dalam bentuk 1 : n secara berasingan bagi subsoalan (a) dan (b).','Gunakan pecahan bertingkat berkurungan untuk memahami skala sebagai panjang lukisan berbanding panjang objek.','Darabkan panjang sisi pada lukisan dengan n untuk memperoleh panjang sebenar.','Jika n ialah pecahan, kekalkan pecahan itu dalam kurungan semasa pendaraban.','Ulang pengiraan menggunakan nilai n yang kedua dan nyatakan unit bagi kedua-dua jawapan.'],[`Skala = (${f('panjang sisi lukisan berskala','panjang sisi objek')})`,'Bagi skala 1 : n, panjang sisi objek = n × panjang sisi lukisan berskala',`Jika n = (${f('a','b')}), panjang sisi objek = (${f('a','b')}) × panjang sisi lukisan berskala`],[sym('n','sebutan kedua dalam skala 1 : n'),sym('Sisi lukisan','sisi berlabel tanda prima pada rajah berskala'),sym('Sisi objek','sisi sebenar yang sepadan tanpa tanda prima'),sym('(a), (b)','dua pengiraan berasingan menggunakan skala yang berlainan')]);
      if(method==='scale-drawing-map-distance-km')return set('scale-drawing-map-distance-km',objective,['Baca skala peta 1 : n dan jarak yang diukur pada peta.','Andaikan jarak sebenar sebagai x dan pastikan kedua-dua jarak dalam unit sentimeter.','Bina dua pecahan setara: 1 cm berbanding n cm dan jarak peta berbanding x.','Darab silang untuk mencari x dalam sentimeter.','Tukarkan sentimeter kepada kilometer menggunakan pecahan bertingkat berkurungan dengan 100 000 cm sebagai penyebut.','Nyatakan jawapan akhir dalam km seperti yang diminta.'],[`Skala = (${f('jarak pada peta','jarak sebenar')})`,`(${f('1 cm','n cm')}) = (${f('jarak pada peta','x cm')})`,`x = (${f('jarak pada peta × n cm','1 cm')})`,`Jarak dalam km = (${f('jarak sebenar dalam cm','100 000 cm')}) km`],[sym('n','sebutan kedua dalam skala 1 : n'),sym('x','jarak sebenar yang belum diketahui'),sym('cm','sentimeter; unit yang digunakan semasa membina nisbah skala'),sym('km','kilometer; unit jawapan akhir'),sym('100 000 cm','bersamaan dengan 1 km')]);
      if(method==='scale-drawing-map-length-from-actual')return set('scale-drawing-map-length-from-actual',objective,['Kenal pasti jarak sebenar dalam kilometer dan skala peta 1 : n.','Andaikan jarak pada peta sebagai x cm.','Tukarkan jarak sebenar daripada kilometer kepada sentimeter dengan mendarab 100 000.','Bina dua pecahan setara: 1 cm berbanding n cm dan x cm berbanding jarak sebenar dalam cm.','Darab silang untuk mencari x dan tulis jawapan dalam sentimeter.','Semak bahawa jarak pada peta lebih kecil daripada jarak sebenar bagi skala pengecilan.'],[`1 km = 100 000 cm`,`Skala = (${f('jarak pada peta','jarak sebenar')})`,`(${f('1 cm','n cm')}) = (${f('x cm','jarak sebenar dalam cm')})`,`x = (${f('1 cm × jarak sebenar dalam cm','n cm')})`],[sym('n','sebutan kedua dalam skala 1 : n'),sym('x','jarak pada peta yang belum diketahui, dalam cm'),sym('Jarak sebenar','jarak antara dua tempat sebelum dikecilkan pada peta'),sym('100 000 cm','bersamaan dengan 1 km')]);
      if(method==='scale-drawing-reconstruct-actual-grid')return set('scale-drawing-reconstruct-actual-grid',objective,['Baca skala pembesaran 1 : satu per n dan kenal pasti bahawa lukisan ialah n kali lebih besar daripada objek sebenar.','Padankan setiap sisi bertanda prima pada lukisan dengan sisi tanpa tanda prima pada objek sebenar.','Gunakan pecahan bertingkat berkurungan untuk membahagikan setiap ukuran lukisan dengan n.','Ulang pengiraan bagi semua sisi yang diberi.','Pada grid dengan petak sama saiz, kecilkan setiap koordinat bucu menggunakan faktor satu per n.','Sambungkan bucu dalam susunan yang sama untuk menghasilkan bentuk sebenar.'],[`Skala = (${f('panjang sisi lukisan berskala','panjang sisi objek')}) = 1 : (${f('1','n')})`,`Panjang sisi objek = (${f('panjang sisi lukisan','n')})`,`Koordinat objek = (${f('koordinat lukisan','n')})`],[sym('n','faktor pembesaran lukisan berbanding objek sebenar'),sym('Tanda prima','label seperti A′ yang menunjukkan bucu pada lukisan berskala'),sym('Tanpa tanda prima','label seperti A yang menunjukkan bucu objek sebenar'),sym('Grid sama saiz','petak pada kedua-dua rajah mempunyai ukuran yang sama')]);
      if(method==='scale-drawing-grid-cell-scale')return set('scale-drawing-grid-cell-scale',objective,['Kenal pasti saiz sisi satu petak bagi lukisan berskala dan bagi objek asal.','Pastikan kedua-dua ukuran grid menggunakan unit yang sama.','Tulis nisbah dalam urutan saiz grid lukisan kepada saiz grid objek.','Gunakan pecahan bertingkat berkurungan untuk membahagikan kedua-dua sebutan dengan saiz grid lukisan.','Tulis nisbah akhir dalam bentuk 1 : n.','Jika n melebihi 1, lukisan ialah pengecilan berbanding objek.'],[`Skala = (${f('saiz grid lukisan berskala','saiz grid objek')})`,`a : b = (${f('a','a')}) : (${f('b','a')}) = 1 : (${f('b','a')})`,'n > 1 → lukisan lebih kecil daripada objek'],[sym('Saiz grid lukisan','panjang sisi satu petak pada lukisan berskala'),sym('Saiz grid objek','panjang sisi satu petak pada objek asal'),sym('n','faktor pengecilan dalam skala 1 : n'),sym('cm','sentimeter; unit bagi panjang sisi petak grid')]);
      if(method==='scale-drawing-model-actual-length-m')return set('scale-drawing-model-actual-length-m',objective,['Kenal pasti panjang model dalam sentimeter dan nilai n dalam skala 1 : n.','Tulis skala sebagai pecahan panjang model di atas panjang sebenar.','Bina kadaran menggunakan ukuran model yang diberi dan skala 1 : n.','Darab panjang model dengan n untuk mendapatkan panjang sebenar dalam sentimeter.','Tukar sentimeter kepada meter menggunakan pecahan bertingkat berkurungan dengan penyebut 100 cm.','Semak bahawa pilihan jawapan ialah pernyataan panjang sebenar dalam unit meter.'],[`Skala = (${f('panjang model','panjang sebenar')}) = 1 : n`,'Panjang sebenar = panjang model × n',`Panjang dalam m = (${f('panjang dalam cm','100 cm')}) m`],[sym('n','nombor kedua dalam skala 1 : n; faktor yang digunakan untuk membesarkan panjang model kepada panjang sebenar'),sym('Panjang model','ukuran model dalam sentimeter yang ditunjukkan pada rajah'),sym('Panjang sebenar','ukuran objek sebenar yang dicari'),sym('100 cm','bersamaan dengan 1 m'),sym('m','meter, unit jawapan akhir')]);
      if(method==='scale-drawing-surface-area-price-story')return set('scale-drawing-surface-area-price-story',objective,['Kenal pasti dua ukuran pada lukisan, skala 1 : n dan kadar harga bagi setiap meter persegi.','Darab setiap ukuran lukisan dengan n untuk mendapatkan ukuran sebenar dalam sentimeter.','Tukar setiap ukuran sebenar daripada sentimeter kepada meter menggunakan pecahan bertingkat berkurungan dengan penyebut 100 cm.','Darab dua ukuran sebenar dalam meter untuk memperoleh luas permukaan dalam meter persegi.','Darab luas permukaan dengan kadar harga yang diberikan.','Tulis jawapan akhir sebagai pernyataan lengkap dalam Ringgit Malaysia.'],[`Skala = (${f('ukuran lukisan berskala','ukuran sebenar')}) = 1 : n`,'Ukuran sebenar = ukuran lukisan × n',`Ukuran dalam m = (${f('ukuran dalam cm','100 cm')}) m`,'Luas permukaan = panjang sebenar × lebar atau tinggi sebenar','Harga = luas permukaan × kadar bagi setiap meter persegi'],[sym('n','nombor kedua dalam skala 1 : n'),sym('Ukuran lukisan','panjang, lebar atau tinggi yang diberi pada lukisan berskala'),sym('Ukuran sebenar','ukuran objek selepas faktor skala digunakan'),sym('m²','meter persegi, unit luas permukaan'),sym('RM','Ringgit Malaysia'),sym('100 cm','bersamaan dengan 1 m')]);
      if(method==='trigonometry-identify-hypotenuse-opposite-adjacent')return set('trigonometry-identify-hypotenuse-opposite-adjacent',objective,['Cari tanda sudut tegak 90° pada rajah.','Namakan sisi yang bertentangan dengan sudut tegak sebagai hipotenus.','Cari kedudukan sudut rujukan θ.','Namakan sisi yang tidak menyentuh θ sebagai sisi bertentangan.','Daripada dua sisi yang menyentuh θ, namakan sisi yang bukan hipotenus sebagai sisi bersebelahan.','Padankan ketiga-tiga nama sisi dengan satu pernyataan pilihan jawapan.'],['Hipotenus = sisi yang bertentangan dengan sudut 90°.','Sisi bertentangan = sisi yang bertentangan dengan sudut θ.','Sisi bersebelahan = sisi yang menyentuh θ tetapi bukan hipotenus.'],[sym('θ','sudut tirus yang menjadi sudut rujukan'),sym('Hipotenus','sisi terpanjang dan bertentangan dengan sudut tegak'),sym('Sisi bertentangan','sisi yang tidak menyentuh sudut θ'),sym('Sisi bersebelahan','sisi yang menyentuh sudut θ dan bukan hipotenus'),sym('90°','sudut tegak')]);
      if(method==='trigonometry-write-ratio-in-side-symbols')return set('trigonometry-write-ratio-in-side-symbols',objective,['Cari sudut tegak dan kenal pasti hipotenus.','Gunakan sudut yang dinyatakan dalam soalan sebagai sudut rujukan.','Kenal pasti sisi bertentangan dan sisi bersebelahan relatif kepada sudut rujukan.','Pilih rumus sinus, kosinus atau tangen yang diminta.','Gantikan nama sisi dengan simbol x, y atau z pada rajah.','Tulis operasi bahagi sebagai pecahan bertingkat di dalam kurungan.'],[`sin θ = (${f('sisi bertentangan','hipotenus')})`,`kos θ = (${f('sisi bersebelahan','hipotenus')})`,`tan θ = (${f('sisi bertentangan','sisi bersebelahan')})`],[sym('θ','sudut tirus yang menjadi sudut rujukan'),sym('sin','nisbah sisi bertentangan kepada hipotenus'),sym('kos','nisbah sisi bersebelahan kepada hipotenus'),sym('tan','nisbah sisi bertentangan kepada sisi bersebelahan'),sym('x, y, z','simbol yang mewakili panjang sisi pada rajah')]);
      if(method==='trigonometry-compare-acute-angle-ratios')return set('trigonometry-compare-acute-angle-ratios',objective,['Pastikan kedua-dua sudut yang dibandingkan ialah sudut tirus antara 0° dengan 90°.','Kenal pasti sama ada pernyataan melibatkan sinus, kosinus atau tangen.','Bandingkan saiz kedua-dua sudut tanpa mengira nilai perpuluhan nisbah.','Bagi sinus dan tangen, nilai bertambah apabila sudut bertambah.','Bagi kosinus, nilai berkurang apabila sudut bertambah.','Pilih simbol “<” atau “>” dan semak bahawa pernyataan akhir sepadan dengan petua tersebut.'],[`sin θ = (${f('sisi bertentangan','hipotenus')})`,`kos θ = (${f('sisi bersebelahan','hipotenus')})`,`tan θ = (${f('sisi bertentangan','sisi bersebelahan')})`,'0° < θ < 90°: sin θ dan tan θ bertambah apabila θ bertambah','0° < θ < 90°: kos θ berkurang apabila θ bertambah'],[sym('θ','sudut tirus yang dibandingkan'),sym('sin','nilai bertambah apabila sudut tirus bertambah'),sym('kos','nilai berkurang apabila sudut tirus bertambah'),sym('tan','nilai bertambah apabila sudut tirus bertambah'),sym('<','lebih kecil daripada'),sym('>','lebih besar daripada')]);
      if(method==='trigonometry-find-sine-from-side-lengths')return set('trigonometry-find-sine-from-side-lengths',objective,['Cari tanda sudut tegak dan kenal pasti hipotenus sebagai sisi yang bertentangan dengan sudut 90°.','Cari kedudukan sudut θ dan kenal pasti sisi bertentangan sebagai sisi yang tidak menyentuh θ.','Masukkan panjang sisi bertentangan sebagai pengangka dan panjang hipotenus sebagai penyebut.','Paparkan operasi bahagi sebagai pecahan bertingkat di dalam kurungan.','Permudahkan pecahan menggunakan faktor sepunya terbesar dan semak bahawa nilai sinus berada antara 0 dengan 1.'],[`sin θ = (${f('sisi bertentangan','hipotenus')})`,`sin θ = (${f('panjang sisi bertentangan','panjang hipotenus')})`],[sym('θ','sudut tirus yang menjadi sudut rujukan'),sym('sin θ','nisbah panjang sisi bertentangan kepada panjang hipotenus'),sym('Hipotenus','sisi terpanjang yang bertentangan dengan sudut tegak'),sym('Sisi bertentangan','sisi yang tidak menyentuh sudut θ'),sym('FSTB','faktor sepunya terbesar untuk memudahkan pengangka dan penyebut')]);
      if(method==='trigonometry-find-cosine-from-side-lengths')return set('trigonometry-find-cosine-from-side-lengths',objective,['Cari tanda sudut tegak dan kenal pasti hipotenus sebagai sisi yang bertentangan dengan sudut 90°.','Cari kedudukan sudut x dan kenal pasti sisi bersebelahan sebagai sisi yang menyentuh x tetapi bukan hipotenus.','Masukkan panjang sisi bersebelahan sebagai pengangka dan panjang hipotenus sebagai penyebut.','Paparkan operasi bahagi sebagai pecahan bertingkat di dalam kurungan.','Permudahkan pecahan menggunakan faktor sepunya terbesar dan semak bahawa nilai kosinus berada antara 0 dengan 1.'],[`kos x = (${f('sisi bersebelahan','hipotenus')})`,`kos x = (${f('panjang sisi bersebelahan','panjang hipotenus')})`],[sym('x','sudut tirus yang menjadi sudut rujukan'),sym('kos x','nisbah panjang sisi bersebelahan kepada panjang hipotenus'),sym('Hipotenus','sisi terpanjang yang bertentangan dengan sudut tegak'),sym('Sisi bersebelahan','sisi yang menyentuh sudut x tetapi bukan hipotenus'),sym('FSTB','faktor sepunya terbesar untuk memudahkan pengangka dan penyebut')]);
      if(method==='trigonometry-find-tangent-from-side-lengths')return set('trigonometry-find-tangent-from-side-lengths',objective,['Cari kedudukan sudut y pada segi tiga bersudut tegak.','Kenal pasti sisi bertentangan sebagai sisi yang tidak menyentuh sudut y.','Kenal pasti sisi bersebelahan sebagai sisi yang menyentuh y tetapi bukan hipotenus.','Masukkan panjang sisi bertentangan sebagai pengangka dan panjang sisi bersebelahan sebagai penyebut.','Paparkan operasi bahagi sebagai pecahan bertingkat di dalam kurungan dan permudahkan menggunakan faktor sepunya terbesar.'],[`tan y = (${f('sisi bertentangan','sisi bersebelahan')})`,`tan y = (${f('panjang sisi bertentangan','panjang sisi bersebelahan')})`],[sym('y','sudut tirus yang menjadi sudut rujukan'),sym('tan y','nisbah panjang sisi bertentangan kepada panjang sisi bersebelahan'),sym('Sisi bertentangan','sisi yang tidak menyentuh sudut y'),sym('Sisi bersebelahan','sisi yang menyentuh sudut y tetapi bukan hipotenus'),sym('FSTB','faktor sepunya terbesar untuk memudahkan pengangka dan penyebut')]);
      if(method==='trigonometry-composite-three-part-ratios')return set('trigonometry-composite-three-part-ratios',objective,['Pisahkan rajah kepada segi tiga kecil dan segi tiga besar.','Bagi (a), gunakan sisi bertentangan dan hipotenus segi tiga kecil untuk mencari sin x.','Bagi (b), tambah dua bahagian pada garis lurus untuk memperoleh keseluruhan sisi tegak, kemudian cari kos y.','Bagi (c), gunakan Teorem Pythagoras pada segi tiga besar untuk mencari sisi dasar.','Gunakan sisi dasar dan keseluruhan sisi tegak untuk mencari tan y.','Permudahkan semua pecahan dan padankan ketiga-tiga jawapan dalam satu kotak pilihan.'],[`sin x = (${f('sisi bertentangan dalam segi tiga kecil','hipotenus segi tiga kecil')})`,`kos y = (${f('sisi bersebelahan dalam segi tiga besar','hipotenus segi tiga besar')})`,'Sisi dasar² = hipotenus² − sisi tegak²',`tan y = (${f('sisi bertentangan dalam segi tiga besar','sisi bersebelahan dalam segi tiga besar')})`],[sym('x','sudut rujukan pada segi tiga kecil'),sym('y','sudut rujukan pada segi tiga besar'),sym('sin x','nisbah sisi bertentangan kepada hipotenus'),sym('kos y','nisbah sisi bersebelahan kepada hipotenus'),sym('tan y','nisbah sisi bertentangan kepada sisi bersebelahan'),sym('(a), (b), (c)','tiga jawapan yang digabungkan dalam satu pilihan')]);
      if(method==='trigonometry-exact-special-angle-expression')return set('trigonometry-exact-special-angle-expression',objective,['Kenal pasti semua sudut khas 30°, 45° atau 60° dalam ungkapan.','Gunakan nisbah sisi segi tiga 30°–60°–90° atau 45°–45°–90° untuk mendapatkan nilai tepat.','Gantikan setiap nisbah trigonometri dengan nombor, surd atau pecahan bertingkat yang sepadan.','Selesaikan pendaraban dan pekali sebelum penambahan atau penolakan.','Samakan penyebut apabila menggabungkan pecahan.','Kekalkan jawapan dalam bentuk tepat tanpa menggunakan nilai perpuluhan.'],[`sin 30° = (${f('1','2')})`,`kos 60° = (${f('1','2')})`,`sin 45° = kos 45° = (${f('√2','2')})`,`sin 60° = kos 30° = (${f('√3','2')})`,`tan 30° = (${f('√3','3')})`,'tan 45° = 1','tan 60° = √3'],[sym('30°, 45°, 60°','sudut khas yang mempunyai nilai trigonometri tepat'),sym('√2, √3','surd yang dikekalkan dalam jawapan tepat'),sym('sin','nisbah sisi bertentangan kepada hipotenus'),sym('kos','nisbah sisi bersebelahan kepada hipotenus'),sym('tan','nisbah sisi bertentangan kepada sisi bersebelahan')]);
      if(method==='trigonometry-find-acute-angle-from-two-sides')return set('trigonometry-find-acute-angle-from-two-sides',objective,['Cari sudut tegak dan kenal pasti kedudukan sudut x pada rajah.','Labelkan dua sisi yang diberi sebagai sisi bertentangan, sisi bersebelahan atau hipotenus relatif kepada x.','Pilih sin, kos atau tan yang menggunakan tepat dua sisi tersebut.','Gantikan ukuran sisi ke dalam nisbah sebagai pecahan bertingkat di dalam kurungan.','Gunakan fungsi songsang sin⁻¹, kos⁻¹ atau tan⁻¹ untuk mencari x.','Bundarkan nilai kalkulator kepada darjah terdekat.'],[`sin x = (${f('sisi bertentangan','hipotenus')})`,`kos x = (${f('sisi bersebelahan','hipotenus')})`,`tan x = (${f('sisi bertentangan','sisi bersebelahan')})`,`x = sin⁻¹(${f('sisi bertentangan','hipotenus')})`,`x = kos⁻¹(${f('sisi bersebelahan','hipotenus')})`,`x = tan⁻¹(${f('sisi bertentangan','sisi bersebelahan')})`],[sym('x','sudut tirus yang dicari'),sym('sin⁻¹','fungsi songsang sinus untuk mencari sudut'),sym('kos⁻¹','fungsi songsang kosinus untuk mencari sudut'),sym('tan⁻¹','fungsi songsang tangen untuk mencari sudut'),sym('°','darjah')]);
      if(method==='trigonometry-composite-two-right-triangles')return set('trigonometry-composite-two-right-triangles',objective,['Asingkan rajah gabungan kepada segi tiga pertama dan segi tiga kedua.','Dalam segi tiga pertama, pilih sinus atau kosinus menggunakan sudut dan sisi yang diberi.','Cari panjang keseluruhan hipotenus segi tiga pertama.','Tolak segmen pendek pada garis yang sama untuk memperoleh panjang sisi yang diminta dalam bahagian (a).','Gunakan panjang bahagian (a) bersama hipotenus segi tiga kedua untuk membina nisbah sinus atau kosinus bagi x.','Gunakan fungsi songsang dan bundarkan x kepada darjah terdekat.'],[`sin θ = (${f('sisi bertentangan','hipotenus')})`,`kos θ = (${f('sisi bersebelahan','hipotenus')})`,'Panjang sisi sambungan = panjang keseluruhan − segmen pendek',`sin x = (${f('sisi bertentangan','hipotenus')})`,`kos x = (${f('sisi bersebelahan','hipotenus')})`,`x = sin⁻¹(${f('sisi bertentangan','hipotenus')}) atau kos⁻¹(${f('sisi bersebelahan','hipotenus')})`],[sym('θ','sudut yang diberi dalam segi tiga pertama'),sym('x','sudut tirus yang dicari dalam bahagian (b)'),sym('sin⁻¹, kos⁻¹','fungsi songsang untuk mendapatkan sudut'),sym('°','darjah')]);
      if(method==='trigonometry-triangular-pyramid-two-angles')return set('trigonometry-triangular-pyramid-two-angles',objective,['Kenal pasti tapak piramid sebagai segi tiga sama kaki.','Oleh sebab titik tengah membahagi sisi tapak kepada dua bahagian sama, cari separuh panjang sisi itu.','Pembahagi dua daripada bucu segi tiga sama kaki menghasilkan dua segi tiga bersudut tegak yang kongruen.','Gunakan sinus dan fungsi songsang untuk mendapatkan separuh sudut tapak, kemudian darab dengan 2.','Gunakan Teorem Pythagoras untuk mencari garis dari bucu tapak ke titik tengah.','Gunakan tangen dan fungsi songsang dalam segi tiga menegak untuk mencari sudut bahagian (b).'],[`Separuh sisi tapak = (${f('panjang sisi tapak','2')})`,`sin α = (${f('separuh sisi tapak','sisi sama panjang')})`,'Sudut penuh = 2 × α',`garis tengah = √(sisi sama panjang² − separuh sisi tapak²)`,`tan β = (${f('tinggi piramid','garis tengah')})`,`β = tan⁻¹(${f('tinggi piramid','garis tengah')})`],[sym('α','separuh sudut pada bucu tapak'),sym('β','sudut dalam segi tiga menegak'),sym('sin⁻¹, tan⁻¹','fungsi songsang untuk mendapatkan sudut'),sym('°','darjah')]);
      if(method==='trigonometry-two-objects-angle-of-depression-distance')return set('trigonometry-two-objects-angle-of-depression-distance',objective,['Kenal pasti tinggi pemerhati, jarak objek dekat dan beza sudut antara dua garis pandangan.','Bina segi tiga bersudut tegak bagi objek yang lebih dekat.','Gunakan tangen dan fungsi songsang untuk mencari sudut pandangan ke objek dekat.','Tambah beza sudut untuk mendapatkan sudut pandangan ke objek jauh.','Gunakan tangen sekali lagi untuk mencari jarak mengufuk objek jauh dari kaki struktur.','Tolak jarak objek dekat daripada jarak objek jauh.'],[`tan α = (${f('jarak objek dekat','tinggi pemerhati')})`,`α = tan⁻¹(${f('jarak objek dekat','tinggi pemerhati')})`,'β = α + beza sudut',`tan β = (${f('jarak objek jauh','tinggi pemerhati')})`,'Jarak objek jauh = tinggi pemerhati × tan β','Jarak antara objek = jarak objek jauh − jarak objek dekat'],[sym('α','sudut pandangan ke objek yang lebih dekat'),sym('β','sudut pandangan ke objek yang lebih jauh'),sym('tan⁻¹','fungsi songsang tangen'),sym('°','darjah'),sym('m','meter')]);
      if(method==='trigonometry-angle-of-elevation-horizontal-line')return set('trigonometry-angle-of-elevation-horizontal-line',objective,['Kenal pasti garisan mengufuk yang melalui aras mata pemerhati.','Sudut di antara garisan mengufuk dengan garis pandangan ke atas ialah sudut dongak.','Bentuk segi tiga bersudut tegak menggunakan kenaikan menegak dan jarak mengufuk.','Gunakan nisbah tangen kerana kedua-dua sisi itu ialah sisi bertentangan dan sisi bersebelahan.','Jika mencari tinggi, darabkan jarak mengufuk dengan tan sudut dan tambah aras mata.','Jika mencari jarak, bahagikan kenaikan menegak dengan tan sudut.'],[`tan θ = (${f('kenaikan menegak','jarak mengufuk')})`,'Kenaikan menegak = jarak mengufuk × tan θ','Tinggi penuh = kenaikan menegak + aras mata',`Jarak mengufuk = (${f('tinggi penuh − aras mata','tan θ')})`],[sym('θ','sudut dongak pada garisan mengufuk'),sym('tan','nisbah sisi bertentangan kepada sisi bersebelahan'),sym('m','meter'),sym('°','darjah')]);
      if(method==='trigonometry-find-elevation-depression-angle')return set('trigonometry-find-elevation-depression-angle',objective,['Kenal pasti garisan mengufuk yang melalui aras mata pemerhati.','Garis pandangan ke atas membentuk sudut dongak, manakala garis pandangan ke bawah membentuk sudut tunduk.','Beza ketinggian ialah sisi bertentangan dan jarak mengufuk ialah sisi bersebelahan.','Gunakan nisbah tangen, kemudian gunakan tan⁻¹ untuk mencari sudut.','Bundarkan sudut kepada darjah terdekat seperti yang diminta.'],[`tan θ = (${f('beza ketinggian','jarak mengufuk')})`,`θ = tan⁻¹(${f('beza ketinggian','jarak mengufuk')})`],[sym('θ','sudut dongak atau sudut tunduk pada garisan mengufuk'),sym('tan','nisbah sisi bertentangan kepada sisi bersebelahan'),sym('tan⁻¹','fungsi songsang tangen untuk mencari sudut'),sym('°','darjah')]);
      if(method==='circle-inscribed-angles-same-arc')return set('circle-inscribed-angles-same-arc',objective,['Kenal pasti kedua-dua titik hujung lengkok yang dicangkum.','Periksa bahawa setiap bucu sudut terletak pada lilitan bulatan.','Senaraikan semua sudut yang mempunyai dua lengan menuju ke titik hujung lengkok yang sama.','Gunakan sifat bahawa sudut pada lilitan yang dicangkum oleh lengkok yang sama adalah sama besar.','Samakan x dan y dengan sudut yang diberi.'],['Sudut pada lilitan yang dicangkum oleh lengkok yang sama adalah sama besar','∠APB = ∠AQB = ∠ARB jika ketiga-tiganya dicangkum oleh lengkok AB'],[sym('x, y','sudut pada lilitan yang belum diketahui'),sym('∠APB','sudut dengan bucu di P dan lengan PA serta PB'),sym('Lengkok AB','bahagian lilitan antara titik A dengan B yang mencangkum sudut berkenaan'),sym('°','darjah')]);
      if(method==='circle-inscribed-intersection-two-unknowns')return set('circle-inscribed-intersection-two-unknowns',objective,['Cari pasangan sudut pada lilitan yang dicangkum oleh lengkok pertama untuk memperoleh x.','Cari satu lagi pasangan sudut pada lilitan yang dicangkum oleh lengkok kedua.','Kenal pasti segi tiga yang terbentuk oleh dua perentas bersilang.','Sudut pada satu bucu segi tiga boleh terdiri daripada y bersama sudut yang diperoleh daripada lengkok kedua.','Gunakan hasil tambah sudut dalam segi tiga untuk mencari y.'],['Sudut pada lilitan yang dicangkum oleh lengkok yang sama adalah sama besar','Hasil tambah sudut dalam segi tiga = 180°','y + sudut daripada lengkok kedua + sudut persilangan + x = 180°'],[sym('x, y','dua sudut yang belum diketahui'),sym('F','titik persilangan dua perentas dalam contoh umum'),sym('∠ABC','sudut dengan bucu di B'),sym('°','darjah')]);
      if(method==='circle-equal-arcs-and-inscribed-angles')return set('circle-equal-arcs-and-inscribed-angles',objective,['Kenal pasti dua lengkok atau dua sudut pada lilitan yang ditandakan sama.','Jika dua lengkok sama panjang, sudut pada lilitan yang dicangkum olehnya adalah sama besar.','Jika dua sudut pada lilitan sama besar, lengkok yang dicangkum olehnya adalah sama panjang.','Padankan pasangan sudut dengan pasangan titik hujung lengkok yang betul.','Salin nilai sudut atau panjang lengkok yang sepadan untuk memperoleh x.'],['Lengkok AB = lengkok CD ⇒ ∠APB = ∠CPD','∠APB = ∠CPD ⇒ panjang lengkok AB = panjang lengkok CD'],[sym('x','sudut atau panjang lengkok yang belum diketahui'),sym('∠APB','sudut pada lilitan dengan bucu di P'),sym('Lengkok AB','bahagian lilitan dari A ke B'),sym('°','darjah'),sym('cm','sentimeter')]);
      if(method==='circle-central-angles-and-equal-arcs')return set('circle-central-angles-and-equal-arcs',objective,['Kenal pasti pusat O, empat jejari, sudut pusat dan lengkok yang dibandingkan.','Bagi dua garis lurus yang bersilang di O, sudut bertentangan bucu adalah sama besar.','Sudut pusat yang sama besar mencangkum lengkok yang sama panjang, dan lengkok sama panjang mencangkum sudut pusat yang sama besar.','Jika dua sudut pusat dilabel x, gunakan jumlah sudut pada satu titik, iaitu 360°.','Kumpulkan dua sebutan x, tolak sudut yang diketahui dan wakili operasi bahagi dua sebagai pecahan bertingkat berkurungan.'],['Sudut bertentangan bucu adalah sama besar','Sudut pusat sama besar ⇔ lengkok sama panjang','Jumlah sudut pada pusat O = 360°',`x = (${f('360° − jumlah sudut yang diketahui','2')})`],[sym('O','pusat bulatan'),sym('x','panjang lengkok atau sudut pusat yang belum diketahui'),sym('∠AOB','sudut pusat dengan bucu di O'),sym('°','darjah'),sym('cm','sentimeter')]);
      if(method==='circle-arc-length-inscribed-angle-ratio')return set('circle-arc-length-inscribed-angle-ratio',objective,['Kenal pasti sudut pada lilitan dan lengkok yang dicangkum oleh setiap sudut.','Susun nisbah sudut dalam urutan yang sama dengan nisbah panjang lengkok.','Gantikan nisbah lengkok yang diberi dan sudut yang diketahui.','Darabkan sudut yang diketahui dengan nisbah lengkok menggunakan pecahan bertingkat berkurungan.','Semak bahawa lengkok yang lebih panjang mencangkum sudut pada lilitan yang lebih besar.'],[`${f('∠QBR','∠PAQ')} = ${f('panjang lengkok QR','panjang lengkok PQ')}`,`x = (${f('nisbah lengkok sasaran','nisbah lengkok rujukan')}) × sudut diberi`],[sym('x','sudut pada lilitan yang belum diketahui'),sym('∠PAQ','sudut pada lilitan yang mencangkum lengkok PQ'),sym('Lengkok PQ','bahagian lilitan dari P ke Q'),sym('°','darjah')]);
      if(method==='circle-central-and-inscribed-angle-relation')return set('circle-central-and-inscribed-angle-relation',objective,['Kenal pasti pusat O, dua jejari dan dua perentas yang membentuk sudut pada lilitan.','Tentukan sama ada sudut pada lilitan mencangkum lengkok kecil atau lengkok refleks.','Bagi lengkok yang sama, sudut pada pusat ialah dua kali sudut pada lilitan.','Jika sudut pusat kecil diberi tetapi sudut pada lilitan mencangkum lengkok refleks, cari sudut refleks menggunakan 360° − sudut pusat kecil.','Wakili operasi membahagi sudut refleks dengan 2 sebagai pecahan bertingkat berkurungan.'],['Sudut pada pusat = 2 × sudut pada lilitan','Sudut refleks = 360° − sudut pusat kecil',`Sudut pada lilitan = (${f('sudut refleks','2')})`],[sym('O','pusat bulatan'),sym('x','sudut yang belum diketahui'),sym('∠AOB','sudut pada pusat dengan bucu di O'),sym('∠ACB','sudut pada lilitan'),sym('°','darjah')]);
      if(method==='circle-diameter-and-composite-angle')return set('circle-diameter-and-composite-angle',objective,['Kenal pasti garis yang melalui pusat O dan menghubungkan dua titik pada lilitan sebagai diameter.','Gunakan sifat bahawa sudut pada lilitan yang dicangkum oleh diameter ialah 90°.','Bagi rajah gabungan, cari dahulu sudut pada lilitan daripada sudut pusat menggunakan pecahan bertingkat berkurungan.','Bahagikan sudut tegak kepada sudut-sudut kecil yang ditunjukkan pada rajah.','Bina persamaan hasil tambah sudut dan asingkan x.'],['Sudut pada lilitan yang dicangkum oleh diameter = 90°',`Sudut pada lilitan = (${f('sudut pada pusat','2')})`,'Hasil tambah sudut dalam segi tiga = 180°'],[sym('O','pusat bulatan'),sym('x','sudut yang belum diketahui'),sym('diameter','perentas yang melalui pusat bulatan'),sym('∠ABC','sudut pada lilitan'),sym('°','darjah')]);
      if(method==='circle-two-tangent-circles-three-angles')return set('circle-two-tangent-circles-three-angles',objective,['Kenal pasti dua bulatan yang bersentuh, pusat kedua-duanya dan dua garis lurus yang bersilang di titik sentuhan.','Cari sudut pada lilitan bagi (a) dengan meletakkan sudut pusat sebagai pengangka dan 2 sebagai penyebut.','Cari sudut tapak segi tiga sama kaki yang dibentuk oleh dua jejari bulatan besar.','Gunakan sudut bertentangan bucu dan sudut 90° yang dicangkum oleh diameter untuk mencari (b).','Pecahkan sudut di R dan T, kemudian gunakan hasil tambah sudut dalam segi tiga besar untuk mencari (c).','Semak ketiga-tiga jawapan mengikut urutan (a), (b), (c).'],[`Sudut pada lilitan = (${f('sudut pada pusat','2')})`,`Sudut tapak = (${f('180° − sudut puncak','2')})`,'Sudut bertentangan bucu adalah sama besar','Sudut pada lilitan yang dicangkum oleh diameter = 90°','Hasil tambah sudut dalam segi tiga = 180°'],[sym('P, Q','pusat dua bulatan'),sym('T','titik sentuhan dan persilangan dua garis lurus'),sym('∠RST','sudut pada lilitan bulatan besar'),sym('∠UVT','sudut pada lilitan bulatan kecil'),sym('°','darjah')]);
      if(method==='circle-cyclic-quadrilateral-identify-opposite-angle')return set('circle-cyclic-quadrilateral-identify-opposite-angle',objective,['Kenal pasti empat bucu yang membentuk sisi empat kitaran; keempat-empatnya mesti berada pada lilitan bulatan.','Tentukan bucu bagi sudut x dengan melihat huruf yang terletak di antara dua lengannya.','Jejak sisi empat mengikut tertib dan bergerak dua bucu untuk memperoleh bucu yang bertentangan.','Kenal pasti dua perentas yang bertemu pada bucu bertentangan itu.','Namakan sudut dengan menulis bucu bertentangan sebagai huruf tengah.'],['Bucu bertentangan tidak berkongsi satu sisi yang sama','Nama sudut = titik pada lengan pertama – bucu – titik pada lengan kedua','Keempat-empat bucu sisi empat kitaran terletak pada lilitan bulatan'],[sym('x','sudut yang diberi pada salah satu bucu sisi empat'),sym('∠ABC','sudut dengan bucu B'),sym('ABCD','empat bucu sisi empat kitaran mengikut tertib'),sym('O','pusat bulatan jika ditunjukkan')]);
      if(method==='circle-cyclic-quadrilateral-opposite-angle-equations')return set('circle-cyclic-quadrilateral-opposite-angle-equations',objective,['Kenal pasti dua pasangan sudut bertentangan dalam sisi empat kitaran.','Gunakan jumlah 180° untuk membina persamaan yang mengandungi x.','Asingkan x dengan menolak sudut yang diketahui daripada 180°.','Bina persamaan kedua yang mengandungi pekali y dan sudut bertentangannya.','Tolak sudut yang diketahui, kemudian bahagikan menggunakan pecahan bertingkat berkurungan.','Semak bahawa setiap pasangan sudut bertentangan berjumlah 180°.'],['Sudut bertentangan pertama + sudut bertentangan kedua = 180°','x = 180° − sudut bertentangan',`y = (${f('180° − sudut bertentangan','pekali y')})`],[sym('x','nilai sudut pertama yang belum diketahui'),sym('y','nilai pemboleh ubah dalam sudut berpekali'),sym('3y','tiga kali nilai y'),sym('∠ABC','sudut pada bucu B'),sym('°','darjah')]);
      if(method==='circle-cyclic-quadrilateral-exterior-opposite-angles')return set('circle-cyclic-quadrilateral-exterior-opposite-angles',objective,['Kenal pasti sisi empat kitaran dan garis lurus yang memanjangkan salah satu sisinya.','Padankan sudut peluaran pada satu bucu dengan sudut pedalaman pada bucu yang bertentangan.','Samakan kedua-dua sudut itu untuk memperoleh x.','Ulang hubungan yang sama bagi sudut peluaran kedua dan sudut pedalaman berpekali y.','Bahagikan nilai sudut peluaran dengan pekali y menggunakan pecahan bertingkat berkurungan.','Semak semula kedua-dua pasangan sudut peluaran dan pedalaman bertentangan.'],['Sudut peluaran sisi empat kitaran = sudut pedalaman bertentangan','x = sudut pedalaman bertentangan',`y = (${f('sudut peluaran','pekali y')})`],[sym('x','sudut peluaran yang belum diketahui'),sym('y','nilai pemboleh ubah dalam sudut pedalaman'),sym('2y','dua kali nilai y'),sym('∠TRS','sudut peluaran pada R'),sym('°','darjah')]);
      if(method==='circle-cyclic-quadrilateral-two-secants-exterior-angle')return set('circle-cyclic-quadrilateral-two-secants-exterior-angle',objective,['Kenal pasti sisi empat kitaran serta dua sisi bertentangan yang dilanjutkan hingga bertemu di luar bulatan.','Gunakan sifat sudut peluaran untuk memindahkan sudut diberi kepada bucu pedalaman yang bertentangan.','Gunakan sifat yang sama pada bucu kedua untuk memperoleh sudut dalam segi tiga luar.','Pada garis lurus kedua, cari sudut pelengkap dengan menolak sudut pedalaman daripada 180°.','Gunakan hasil tambah sudut dalam segi tiga luar untuk mencari sudut pada titik pertemuan.','Semak jawapan dengan beza dua sudut diberi.'],['Sudut peluaran sisi empat kitaran = sudut pedalaman bertentangan','Sudut pada garis lurus = 180°','Hasil tambah sudut dalam segi tiga = 180°','Sudut pertemuan luar = sudut peluaran pertama − sudut pedalaman kedua'],[sym('P','titik pertemuan dua garis sekan di luar bulatan'),sym('∠APD','sudut sasaran pada titik luar P'),sym('ABCD','sisi empat kitaran'),sym('°','darjah')]);
      if(method==='circle-cyclic-quadrilateral-mixed-interior-exterior')return set('circle-cyclic-quadrilateral-mixed-interior-exterior',objective,['Kenal pasti sisi empat kitaran dan tentukan label yang berada di dalam atau di luar sisi empat.','Bagi sudut pedalaman bertentangan yang sama jenis, bina jumlah 180°.','Bagi sudut peluaran, samakan sudut itu dengan sudut pedalaman pada bucu bertentangan.','Bina persamaan x menggunakan pasangan sudut yang betul.','Ulang proses untuk y dan selesaikan pekali selepas nilai sudut penuh diperoleh.','Paparkan setiap operasi bahagi sebagai pecahan bertingkat di dalam kurungan dan semak kedua-dua jawapan.'],['Sudut pedalaman bertentangan berjumlah 180°','Sudut peluaran sisi empat kitaran = sudut pedalaman bertentangan',`x = (${f('nilai sudut penuh','pekali x')})`,`y = (${f('nilai sudut penuh','pekali y')})`],[sym('x, y','dua nilai pemboleh ubah yang dicari'),sym('2x, 3y','sudut penuh yang mengandungi pekali'),sym('∠ABC','sudut pedalaman dengan bucu di B'),sym('Sudut peluaran','sudut di luar sisi empat yang terbentuk apabila sisi dilanjutkan'),sym('°','darjah')]);
      if(method==='circle-tangent-identification-yes-no')return set('circle-tangent-identification-yes-no',objective,['Fokus pada garis lurus yang dinamakan dalam soalan.','Bayangkan garis itu dilanjutkan tanpa had pada kedua-dua arah.','Kira bilangan titik pertemuan antara garis dengan lilitan bulatan.','Jika terdapat satu titik sahaja, semak bahawa jejari ke titik sentuhan berserenjang dengan garis.','Jika garis memotong dua titik atau tidak menyentuh bulatan, garis itu bukan tangen.','Pilih Ya atau Tidak dan nyatakan sebab berdasarkan bilangan titik pertemuan.'],['Tangen menyentuh bulatan pada satu titik sahaja','Jejari pada titik sentuhan ⟂ garis tangen','Dua titik persilangan ⇒ bukan tangen','Tiada titik pertemuan ⇒ bukan tangen'],[sym('O','pusat bulatan dalam contoh umum'),sym('AB','garis lurus yang diperiksa'),sym('⊥','berserenjang'),sym('Ya','garis itu ialah tangen'),sym('Tidak','garis itu bukan tangen')]);
      if(method==='circle-tangent-radius-angle')return set('circle-tangent-radius-angle',objective,['Kenal pasti pusat bulatan, titik ketangenan dan garis tangen yang dinamakan.','Sambungkan pusat kepada titik ketangenan untuk mengenal pasti jejari.','Gunakan sifat bahawa jejari pada titik ketangenan berserenjang dengan garis tangen.','Tandakan sudut pada titik ketangenan sebagai 90°.','Bina persamaan hasil tambah tiga sudut dalam segi tiga, iaitu 180°.','Jika sudut mengandungi pekali x, asingkan sebutan x dan bahagikan menggunakan pecahan bertingkat berkurungan.'],['Jejari ⟂ tangen pada titik ketangenan','Sudut jejari-tangen = 90°','Hasil tambah sudut dalam segi tiga = 180°',`x = (${f('nilai sudut selepas pemindahan','pekali x')})`],[sym('O','pusat bulatan dalam contoh umum'),sym('Q','titik ketangenan dalam contoh umum'),sym('PQR','garis tangen dalam contoh umum'),sym('⊥','berserenjang'),sym('x','nilai sudut yang dicari'),sym('°','darjah')]);
      if(method==='circle-two-tangents-length-angle')return set('circle-two-tangents-length-angle',objective,['Kenal pasti dua garis tangen yang bermula dari titik luar yang sama.','Gunakan sifat bahawa dua tangen dari titik luar yang sama adalah sama panjang untuk menjawab bahagian (a).','Sambungkan pusat bulatan kepada kedua-dua titik ketangenan dan tandakan dua sudut tegak.','Bandingkan dua segi tiga bersudut tegak; jejari adalah sama dan paksi dari titik luar ke pusat ialah sisi sepunya.','Gunakan kesamaan sudut sepadan pada paksi bersama.','Bina persamaan hasil tambah sudut dalam segi tiga untuk bahagian (b); jika ada pekali x, gunakan pecahan bertingkat di dalam kurungan.'],['PA = PB bagi dua tangen dari titik luar P','Jejari ⟂ tangen pada titik ketangenan','Dua segi tiga tangen adalah kongruen','Hasil tambah sudut dalam segi tiga = 180°',`x = (${f('nilai sudut selepas pemindahan','pekali x')})`],[sym('O','pusat bulatan dalam contoh umum'),sym('P','titik luar yang sama'),sym('PA, PB','dua tangen dari P'),sym('⊥','berserenjang'),sym('x','nilai sudut yang dicari'),sym('°','darjah')]);
      if(method==='circle-cyclic-central-two-tangents-angle')return set('circle-cyclic-central-two-tangents-angle',objective,['Kenal pasti sisi empat kitaran dan pasangan sudut pedalaman bertentangan.','Tolak sudut yang diberi daripada 180° untuk mendapatkan sudut pada lilitan yang mencangkum lengkok antara dua titik ketangenan.','Darab sudut pada lilitan itu dengan 2 untuk mendapatkan sudut pada pusat.','Gunakan sifat jejari yang berserenjang dengan tangen untuk membentuk dua sudut tegak.','Sudut antara dua tangen dan sudut pada pusat berjumlah 180°.','Jika sudut sasaran mengandungi pekali x, asingkan x dan tulis operasi bahagi sebagai pecahan bertingkat di dalam kurungan.'],['Sudut bertentangan sisi empat kitaran berjumlah 180°','Sudut pusat = 2 × sudut pada lilitan','Jejari ⟂ tangen','Sudut antara dua tangen + sudut pusat = 180°',`x = (${f('nilai selepas pemindahan','pekali x')})`],[sym('O','pusat bulatan dalam contoh umum'),sym('P, R','dua titik ketangenan'),sym('T','titik luar pertemuan dua tangen'),sym('∠POR','sudut pada pusat'),sym('x','nilai sudut yang dicari'),sym('°','darjah')]);
      if(method==='circle-tangent-chord-alternate-segment-equal-angles')return set('circle-tangent-chord-alternate-segment-equal-angles',objective,['Kenal pasti garis tangen dan titik ketangenan pada bulatan.','Baca dua jejari sudut sasaran: satu pada tangen dan satu pada perentas.','Gunakan teorem tangen–perentas untuk mencari sudut dalam tembereng selang-seli.','Semak bahawa sudut jawapan dicangkum oleh dua hujung perentas yang sama.','Jika dua bucu berada pada tembereng yang sama, kedua-dua sudut pada lilitan itu juga sama.','Bagi soalan gabungan, selesaikan subsoalan (a), (b), (c) dan (d) satu demi satu sebelum memilih satu set jawapan.'],['Sudut antara tangen dan perentas = sudut dalam tembereng selang-seli','Sudut yang dicangkum oleh perentas yang sama adalah sama','Tangen menyentuh bulatan pada satu titik sahaja'],[sym('O','pusat bulatan dalam contoh umum'),sym('B','titik ketangenan dalam contoh rujukan'),sym('ABC','garis tangen dalam contoh rujukan'),sym('BD','contoh perentas yang mencangkum sudut'),sym('∠','simbol sudut')]);
      if(method==='circle-tangent-chord-find-angle-x')return set('circle-tangent-chord-find-angle-x',objective,['Kenal pasti garis tangen dan titik ketangenan.','Cari sudut pada lilitan yang mencangkum perentas yang sama dengan sudut tangen–perentas.','Bagi bentuk garis lurus, gunakan jumlah sudut 180°.','Bagi bentuk sudut terbahagi, tolak sudut kecil daripada sudut tangen–perentas penuh.','Gantikan ungkapan x dan asingkan x.','Jika pekali x perlu dibahagi, gunakan pecahan bertingkat yang diletakkan di dalam kurungan.'],['Sudut tangen–perentas = sudut dalam tembereng selang-seli','Sudut pada garis lurus = 180°',`x = (${f('nilai selepas pemindahan','pekali x')})`],[sym('Q','titik ketangenan dalam contoh umum'),sym('PQR','garis tangen dalam contoh umum'),sym('x','nilai sudut yang dicari'),sym('°','darjah')]);
      if(method==='circle-tangent-isosceles-find-x-y')return set('circle-tangent-isosceles-find-x-y',objective,['Kenal pasti garis tangen, titik ketangenan dan segi tiga sama kaki.','Gunakan teorem sudut antara tangen dengan perentas untuk mendapatkan sudut puncak.','Gunakan dua sisi sama panjang untuk menyamakan dua sudut tapak.','Cari setiap sudut tapak daripada hasil tambah sudut segi tiga 180°.','Samakan ungkapan x dan y dengan sudut tapak yang berkaitan.','Asingkan pemboleh ubah; tulis pembahagian sebagai pecahan bertingkat berkurung.'],['Sudut tangen–perentas = sudut dalam tembereng selang-seli',`Sudut tapak = (${f('180° − sudut puncak','2')})`,`x = (${f('nilai selepas pemindahan','pekali x')})`],[sym('Q','titik ketangenan dalam contoh umum'),sym('QTU','segi tiga sama kaki dalam contoh umum'),sym('x, y','nilai sudut yang dicari'),sym('°','darjah')]);
      if(method==='circle-tangent-diameter-parallel-angle')return set('circle-tangent-diameter-parallel-angle',objective,['Kenal pasti garis tangen, titik ketangenan, diameter dan pasangan garis selari.','Gunakan sifat bahawa sudut pada lilitan yang dicangkum oleh diameter ialah 90°.','Gunakan teorem tangen–perentas untuk memindahkan sudut diberi ke dalam bulatan.','Gunakan sudut selang-seli pada dua garis selari untuk memperoleh sudut kedua dalam segi tiga sasaran.','Tolak dua sudut yang diketahui daripada 180° untuk mencari sudut yang dikehendaki.','Jika variasi seterusnya memerlukan pembahagian, tulis operasi itu sebagai pecahan bertingkat di dalam kurungan.'],['Sudut pada lilitan yang dicangkum oleh diameter = 90°','Sudut tangen–perentas = sudut dalam tembereng selang-seli','Garis selari → sudut selang-seli adalah sama','Hasil tambah sudut dalam segi tiga = 180°'],[sym('ABC','garis tangen dalam contoh rujukan'),sym('B','titik ketangenan dalam contoh rujukan'),sym('EH','diameter dalam contoh rujukan'),sym('BD ∥ EH','pasangan garis selari dalam contoh rujukan'),sym('°','darjah')]);
      if(method==='circle-tangent-cyclic-central-composite-two-angles')return set('circle-tangent-cyclic-central-composite-two-angles',objective,['Kenal pasti garis tangen, sisi empat kitaran, pusat bulatan dan dua jejari.','Untuk bahagian (a), pindahkan sudut tangen–perentas ke sudut pada lilitan yang mencangkum perentas sama.','Gunakan garis lurus 180° untuk mencari sudut pada titik ketangenan di dalam sisi empat kitaran.','Gunakan jumlah 180° bagi sudut pedalaman bertentangan sisi empat kitaran.','Untuk bahagian (b), letakkan sudut pusat sebagai pengangka dan 2 sebagai penyebut untuk mencari sudut pada lilitan.','Cari sudut tapak segi tiga sama kaki menggunakan pecahan bertingkat berkurungan.','Gunakan hasil tambah sudut untuk memperoleh sudut akhir di antara jejari dan perentas.'],['Sudut tangen–perentas = sudut dalam tembereng selang-seli','Sudut pedalaman bertentangan sisi empat kitaran berjumlah 180°',`Sudut pada lilitan = (${f('sudut pada pusat','2')})`,`Sudut tapak = (${f('180° − sudut pusat','2')})`],[sym('O','pusat bulatan dalam contoh rujukan'),sym('Q','titik ketangenan dalam contoh rujukan'),sym('PQR','garis tangen dalam contoh rujukan'),sym('OT, OU','dua jejari yang membentuk segi tiga sama kaki'),sym('(a), (b)','dua sudut yang perlu dicari'),sym('°','darjah')]);
      if(method==='circle-double-tangent-diameter-two-angles')return set('circle-double-tangent-diameter-two-angles',objective,['Kenal pasti diameter, titik luar, dua tangen dan kedua-dua titik ketangenan.','Gunakan jejari yang serenjang dengan tangen untuk mendapatkan sudut antara perentas dan jejari.','Gunakan dua jejari yang sama panjang untuk membina segi tiga sama kaki.','Cari dua sudut pusat yang sepadan, kemudian gunakan jumlah sudut pada satu titik 360°.','Paksi dari titik luar ke pusat membahagi dua sudut antara dua jejari dan sudut antara dua tangen.','Letakkan sudut yang dibahagi sebagai pengangka dan 2 sebagai penyebut dalam pecahan bertingkat berkurungan.'],['Jejari pada titik ketangenan ⟂ tangen','Dua tangen dari titik luar adalah sama panjang',`Sudut separuh = (${f('sudut penuh','2')})`,'Sudut antara dua tangen + sudut pusat = 180°'],[sym('O','pusat bulatan dalam contoh rujukan'),sym('EF','diameter dalam contoh rujukan'),sym('K','titik luar dalam contoh rujukan'),sym('M, N','titik ketangenan dalam contoh rujukan'),sym('(i), (ii)','dua sudut yang perlu dicari'),sym('°','darjah')]);
      if(method==='circle-two-tangents-inscribed-isosceles-three-angles')return set('circle-two-tangents-inscribed-isosceles-three-angles',objective,['Kenal pasti dua tangen dari titik luar, tiga perentas dan segi tiga sama kaki di dalam bulatan.','Gunakan teorem tangen–perentas untuk memindahkan sudut diberi kepada sudut x pada lilitan.','Gunakan dua perentas sama panjang untuk menyamakan sudut tapak segi tiga di dalam bulatan.','Cari setiap sudut tapak dengan meletakkan 180° − x sebagai pengangka dan 2 sebagai penyebut.','Gunakan semula teorem tangen–perentas untuk mendapatkan sudut y.','Dua tangen dari titik luar adalah sama panjang; gunakan jumlah sudut segi tiga 180° untuk mencari z.'],['Sudut tangen–perentas = sudut dalam tembereng selang-seli',`Sudut tapak = (${f('180° − sudut puncak','2')})`,'Dua tangen dari titik luar adalah sama panjang','x + y + z bagi sebuah segi tiga = 180°'],[sym('ABC, ADE','dua garis tangen dalam contoh rujukan'),sym('B, D','titik ketangenan dalam contoh rujukan'),sym('BD = BF','dua perentas sama panjang'),sym('x, y, z','tiga sudut yang perlu dicari'),sym('°','darjah')]);
      if(method==='circle-cyclic-straight-radius-sum')return set('circle-cyclic-straight-radius-sum',objective,['Kenal pasti sisi empat kitaran, garis lurus, sudut peluaran dan dua jejari.','Samakan sudut peluaran dengan sudut pedalaman yang bertentangan dalam sisi empat kitaran.','Pecahkan sudut pedalaman itu kepada sudut x dan sudut diberi untuk mencari x.','Sudut pusat yang dicangkum oleh lengkok yang sama ialah dua kali sudut x pada lilitan.','Dua jejari membentuk segi tiga sama kaki; cari y menggunakan pecahan bertingkat berkurungan.','Jumlahkan nilai x dan y seperti yang diminta dalam soalan.'],['Sudut peluaran sisi empat kitaran = sudut pedalaman bertentangan','Sudut pada pusat = 2 × sudut pada lilitan',`Sudut tapak = (${f('180° − sudut pusat','2')})`,'Jawapan akhir = x + y'],[sym('PQRS','sisi empat kitaran dalam contoh rujukan'),sym('SPT','garis lurus dalam contoh rujukan'),sym('O','pusat bulatan'),sym('OS, OP','dua jejari yang membentuk segi tiga sama kaki'),sym('x, y','dua sudut yang dijumlahkan'),sym('°','darjah')]);
      if(method==='circle-tangent-central-radius-find-x')return set('circle-tangent-central-radius-find-x',objective,['Padankan sudut antara tangen dan perentas dengan sudut dalam tembereng selang-seli.','Tukar sudut pusat kepada sudut pada lilitan menggunakan pecahan bertingkat berpenyebut 2.','Gunakan hasil tambah sudut dalam segi tiga untuk mencari sudut penuh pada bucu sasaran.','Kenal pasti dua jejari yang membentuk segi tiga sama kaki.','Cari sudut tapak segi tiga jejari menggunakan pecahan bertingkat berkurungan.','Tolak sudut tapak daripada sudut penuh pada bucu untuk memperoleh x.'],['Sudut tangen–perentas = sudut dalam tembereng selang-seli',`Sudut pada lilitan = (${f('sudut pusat','2')})`,'Hasil tambah sudut dalam segi tiga = 180°',`Sudut tapak jejari = (${f('180° − sudut pusat','2')})`],[sym('O','pusat bulatan dalam contoh rujukan'),sym('PJQ','garis tangen dengan J sebagai titik ketangenan'),sym('K, M, J','tiga titik pada lilitan bulatan'),sym('OK, OM','dua jejari yang membentuk segi tiga sama kaki'),sym('x','sudut antara jejari dan perentas yang dicari'),sym('°','darjah')]);
      if(method==='orthographic-projection-two-planes')return set('orthographic-projection-two-planes',objective,['Kenal pasti satah mencancang bagi subsoalan (a) dan satah mengufuk bagi subsoalan (b).','Bayangkan garis pandangan yang berserenjang dengan satah sasaran.','Untuk satah mencancang, abaikan kedalaman dan kekalkan lebar serta tinggi.','Untuk satah mengufuk, abaikan tinggi dan kekalkan lebar serta kedalaman.','Jejak bucu, lengkung dan garisan terlindung yang masih perlu ditunjukkan.','Padankan kedua-dua unjuran dengan satu daripada empat pasangan pilihan.'],['Garis pandangan ⟂ satah unjuran','Satah mencancang: lebar × tinggi','Satah mengufuk: lebar × kedalaman',`Titik tengah = (${f('ukuran penuh','2')})`],[sym('⊥','berserenjang atau membentuk sudut 90°'),sym('(a)','unjuran pada satah mencancang'),sym('(b)','unjuran pada satah mengufuk'),sym('Garis putus-putus','garisan atau bucu yang terlindung'),sym('cm','sentimeter')]);
      if(method==='compound-interest-frequency-story')return set('compound-interest-frequency-story',objective,['Kenal pasti prinsipal P, kadar tahunan r, kekerapan kompaun n dan tempoh t daripada cerita.','Tukar kadar peratus kepada perpuluhan menggunakan pecahan bertingkat berkurungan; kadar bagi setiap tempoh ialah r di atas n.','Kira bilangan tempoh kompaun menggunakan n × t.','Kaedah 1: kira faedah setiap tempoh berdasarkan baki awal tempoh itu, kemudian dapatkan baki akhir.','Kaedah 2: gantikan nilai ke dalam rumus nilai matang MV dan hitung kuasa dengan teliti.','Tolak prinsipal asal daripada nilai matang untuk mendapatkan jumlah faedah kompaun.'],[`MV = P(1 + (${f('r','n')}))ⁿᵗ`,`Kadar setiap tempoh = (${f('r','n')})`,'Bilangan tempoh = n × t',`Faedah tempoh semasa = baki awal × (${f('r','n')})`,'Baki akhir = baki awal + faedah tempoh semasa','Jumlah faedah kompaun = MV − P'],[sym('MV','nilai matang atau baki simpanan pada akhir tempoh'),sym('P','prinsipal atau simpanan asal'),sym('r','kadar faedah tahunan dalam bentuk perpuluhan'),sym('n','bilangan kali faedah dikompaun dalam setahun'),sym('t','tempoh simpanan dalam tahun'),sym('n × t','jumlah keseluruhan tempoh pengkompaunan'),sym('RM','Ringgit Malaysia')]);
      if(method==='compound-interest-maturity-story')return set('compound-interest-maturity-story',objective,['Kenal pasti prinsipal P, kadar tahunan r, jarak bulan antara setiap pengkompaunan dan tempoh simpanan.','Tukar kadar peratus kepada perpuluhan menggunakan pecahan bertingkat berkurungan.','Cari n dengan meletakkan 12 bulan sebagai pengangka dan bilangan bulan bagi satu tempoh kompaun sebagai penyebut.','Tukar tempoh kepada tahun jika tempoh diberi dalam bulan, kemudian kira hasil darab n × t.','Gantikan P, r, n dan t ke dalam rumus MV, kemudian hitung nilai matang hingga dua tempat perpuluhan.','Jawapan yang diminta ialah keseluruhan jumlah wang simpanan, bukan faedah sahaja.'],[`MV = P(1 + (${f('r','n')}))ⁿᵗ`,`r = (${f('kadar peratus','100')})`,`n = (${f('12 bulan','bulan bagi satu tempoh kompaun')})`,`t = (${f('tempoh dalam bulan','12 bulan')}) (jika perlu)`,'Bilangan tempoh = n × t'],[sym('MV','nilai matang atau jumlah wang simpanan pada akhir tempoh'),sym('P','prinsipal atau jumlah simpanan asal'),sym('r','kadar faedah tahunan dalam bentuk perpuluhan'),sym('n','bilangan kali faedah dikompaun dalam setahun'),sym('t','tempoh simpanan dalam tahun'),sym('n × t','jumlah keseluruhan tempoh pengkompaunan'),sym('RM','Ringgit Malaysia')]);
      if(method==='compound-interest-maturity-and-interest-story')return set('compound-interest-maturity-and-interest-story',objective,['Kenal pasti P, r, n dan t daripada jalan cerita sebelum menjawab kedua-dua bahagian.','Tukar kadar peratus kepada perpuluhan dan cari n menggunakan pecahan bulan yang berkurungan.','Tukar tempoh bulan kepada tahun jika perlu, kemudian hitung jumlah tempoh kompaun n × t.','Bagi bahagian (a), gantikan semua nilai ke dalam rumus MV untuk mendapatkan jumlah wang simpanan.','Bagi bahagian (b), gunakan nilai matang daripada bahagian (a) dan tolak prinsipal asal.','Nyatakan kedua-dua jawapan mengikut label (a) dan (b) dalam Ringgit Malaysia.'],[`MV = P(1 + (${f('r','n')}))ⁿᵗ`,`r = (${f('kadar peratus','100')})`,`n = (${f('12 bulan','bulan bagi satu tempoh kompaun')})`,`t = (${f('tempoh dalam bulan','12 bulan')}) (jika perlu)`,'Bilangan tempoh = n × t','Jumlah faedah kompaun = MV − P'],[sym('MV','jumlah wang simpanan atau nilai matang bagi bahagian (a)'),sym('P','prinsipal atau simpanan asal'),sym('r','kadar faedah tahunan dalam bentuk perpuluhan'),sym('n','bilangan kali faedah dikompaun dalam setahun'),sym('t','tempoh simpanan dalam tahun'),sym('n × t','jumlah keseluruhan tempoh pengkompaunan'),sym('MV − P','jumlah faedah kompaun bagi bahagian (b)'),sym('RM','Ringgit Malaysia')]);
      const profiles={
        '2-7':[[`Jarak = √((x₂ − x₁)² + (y₂ − y₁)²)`,`Titik tengah = (${f('x₁ + x₂',2)}, ${f('y₁ + y₂',2)})`],[sym('x₁, y₁','koordinat titik pertama'),sym('x₂, y₂','koordinat titik kedua')]],
        '2-8':[['y = f(x)'],[sym('x','nilai input pada paksi mengufuk'),sym('y','nilai output pada paksi mencancang'),sym('f','peraturan fungsi yang diberikan')]],
        '2-9':[[`v = ${f('s','t')}`,`a = ${f('v − u','t')}`],[sym('v','laju atau laju akhir, mengikut formula'),sym('s','jarak'),sym('t','masa'),sym('u','laju awal'),sym('a','pecutan')]],
        '2-10':[[`m = ${f('y₂ − y₁','x₂ − x₁')}`],[sym('m','kecerunan; penyebut bukan sifar bagi garis bukan mencancang'),sym('x₁, y₁','koordinat titik pertama'),sym('x₂, y₂','koordinat titik kedua')]],
        '3-1':[['aᵐ × aⁿ = aᵐ⁺ⁿ','aᵐ ÷ aⁿ = aᵐ⁻ⁿ (a ≠ 0)','(aᵐ)ⁿ = aᵐⁿ'],[sym('a','asas'),sym('m, n','indeks atau kuasa')]],
        '3-2':[['A × 10ⁿ, dengan 1 ≤ A < 10'],[sym('A','nombor antara 1 (termasuk) dan 10 (tidak termasuk)'),sym('n','indeks integer yang menentukan kedudukan titik perpuluhan')]],
        '3-4':[[`Skala = ${f('ukuran lukisan','ukuran sebenar')}`],[sym('1 : n','1 unit pada lukisan mewakili n unit sebenar; samakan unit dahulu'),sym('n','faktor skala dalam nisbah 1 : n')]],
        '3-5':[[`sin θ = ${f('sisi bertentangan','hipotenus')}`,`kos θ = ${f('sisi bersebelahan','hipotenus')}`,`tan θ = ${f('sisi bertentangan','sisi bersebelahan')}`],[sym('θ','sudut rujukan dalam segi tiga bersudut tegak'),sym('sin, kos, tan','nisbah trigonometri; sisi dipilih relatif kepada θ')]],
        '3-6':[['Sudut pusat = 2 × sudut lilitan yang menghadap lengkok sama','Sudut bertentangan sisi empat kitaran berjumlah 180°','Jejari berserenjang dengan tangen di titik sentuhan'],[sym('∠ABC','sudut dengan bucu di B'),sym('Tangen','garis yang menyentuh bulatan pada satu titik')]],
        '3-7':[['Padankan pandangan dari atas (pelan), depan dan sisi; gunakan ukuran serta garis tersembunyi yang betul.'],[sym('Garisan putus-putus','tepi yang terlindung dalam pandangan berkenaan')]],
        '3-8':[['Lokus ialah himpunan semua titik yang memenuhi syarat jarak atau kedudukan dalam soalan.'],[sym('Titik/garis berlabel','objek rujukan bagi syarat lokus; patuhi semua syarat serentak')]],
        '3-9':[['y = mx + c'],[sym('x, y','koordinat titik pada garis'),sym('m','kecerunan'),sym('c','pintasan pada paksi-y')]],
        '4-1':[['y = ax² + bx + c (a ≠ 0)'],[sym('x','pemboleh ubah'),sym('y','nilai fungsi'),sym('a, b, c','pekali dan pemalar bagi fungsi kuadratik')]],
        '4-2':[['Nilai tempat dalam asas b: digit × bⁿ'],[sym('b','asas nombor; digit mestilah kurang daripada b'),sym('n','kedudukan nilai tempat, bermula n = 0 di kanan')]],
        '4-3':[['p ⇒ q','p DAN q benar hanya apabila kedua-duanya benar'],[sym('p, q','pernyataan yang dinilai benar atau palsu'),sym('⇒','implikasi: jika p, maka q')]],
        '4-5':[['Graf terdiri daripada bucu dan tepi yang menghubungkan bucu.'],[sym('Bucu','objek atau nod dalam rangkaian'),sym('Tepi','hubungan antara dua bucu'),sym('Pemberat','nilai pada tepi, seperti jarak atau kos')]],
        '4-7':[['Kecerunan graf jarak-masa = laju','Kecerunan graf laju-masa = pecutan','Luas di bawah graf laju-masa = jarak'],[sym('Paksi mengufuk','masa'),sym('Paksi mencancang','jarak atau laju, mengikut tajuk graf')]],
        '4-8':[['Julat = nilai maksimum − nilai minimum',`Min = ${f('Σx','N')}`],[sym('x','nilai data'),sym('N','bilangan data')]],
        '4-9':[['P(A ∪ B) = P(A) + P(B) − P(A ∩ B)','Jika A dan B bebas: P(A ∩ B) = P(A) × P(B)'],[sym('P(A)','kebarangkalian peristiwa A'),sym('A, B','peristiwa dalam soalan'),sym('∪','kesatuan: A atau B atau kedua-duanya'),sym('∩','persilangan: A dan B')]],
        '5-1':[['Ubahan langsung: y = kx','Ubahan songsang: y = k ÷ x (x ≠ 0)'],[sym('x, y','kuantiti yang berubah'),sym('k','pemalar ubahan; bentuk sebenar hubungan mengikut soalan')]],
        '5-2':[['(AB)ᵢⱼ = Σ aᵢₖbₖⱼ'],[sym('A, B','matriks dengan dimensi yang serasi untuk pendaraban'),sym('aᵢₖ, bₖⱼ','unsur baris/lajur berkenaan'),sym('i, j, k','indeks baris, lajur dan kedudukan hasil darab')]],
        '5-3':[['Premium = jumlah bayaran perlindungan mengikut kadar dan syarat polisi yang diberikan'],[sym('Premium','bayaran untuk perlindungan insurans'),sym('Deduktibel','bahagian tuntutan yang ditanggung sendiri mengikut soalan')]],
        '5-4':[['Cukai = kadar × amaun bercukai bagi lapisan atau kategori yang berkenaan'],[sym('Kadar','peratus atau nilai yang DIBERI dalam soalan; jangan mengandaikan kadar semasa'),sym('Amaun bercukai','nilai selepas pelepasan atau pelarasan yang diberikan')]],
        '5-5':[['Faktor skala panjang = |k|','Faktor skala luas = k²','Faktor skala isi padu = |k|³'],[sym('k','faktor pembesaran; bagi saiz gunakan nilai magnitudnya'),sym('|k|','nilai mutlak k; saiz tidak negatif'),sym('Kongruen','bentuk dan saiz sama')]],
        '5-6':[['y = a sin bx + c'],[sym('y','nilai fungsi atau output graf'),sym('a','pekali yang menentukan amplitud |a|'),sym('b','pekali yang menentukan tempoh'),sym('c','anjakan mencancang'),sym('x','sudut atau input mengikut unit yang dinyatakan')]],
        '5-7':[[`Min anggaran = ${f('Σfx','Σf')}`],[sym('f','kekerapan kelas'),sym('x','titik tengah kelas')]],
        '5-8':[['Model = hubungan kuantiti berdasarkan pemboleh ubah dan andaian yang dinyatakan'],[sym('Pemboleh ubah','kuantiti yang diwakili oleh huruf dalam model'),sym('Parameter','nilai tetap bagi model yang dibina')]]
      };
      if(key==='3-3'||key==='4-10'){
        const text=`${item?.questionText||''} ${item?.hintText||''}`.toLowerCase(),compound=/kompaun|dikompaun/.test(text),loan=/ansuran|bayaran balik/.test(text);let formulas,symbols;
        if(compound){formulas=[`MV = P(1 + ${f('r','n')})ⁿᵗ`,'Faedah kompaun = MV − P'];symbols=[sym('MV','nilai matang'),sym('P','prinsipal atau modal awal'),sym('r','kadar tahunan dalam perpuluhan, bukan peratus terus'),sym('n','bilangan kali dikompaun setahun'),sym('t','tempoh dalam tahun')];}
        else if(/roi|pulangan pelaburan/.test(text)){formulas=[`ROI = ${f('keuntungan bersih','modal awal')} × 100%`];symbols=[sym('ROI','peratus pulangan atas pelaburan')];}
        else if(/dsr|nisbah khidmat hutang/.test(text)){formulas=[`DSR = ${f('komitmen hutang bulanan','pendapatan bulanan')} × 100%`];symbols=[sym('DSR','nisbah khidmat hutang')];}
        else if(/dividen/.test(text)){formulas=['Dividen = bilangan unit × dividen seunit'];symbols=[sym('Dividen seunit','bayaran bagi satu unit saham seperti diberi dalam soalan')];}
        else if(loan){formulas=['Jumlah bayaran balik = P + I',`Ansuran bulanan = ${f('jumlah bayaran balik','bilangan bulan')}`];symbols=[sym('P','jumlah prinsipal pinjaman'),sym('I','jumlah faedah mengikut rumus atau syarat pinjaman dalam soalan')];}
        else{formulas=['I = P × r × t'];symbols=[sym('I','faedah mudah'),sym('P','prinsipal atau modal awal'),sym('r','kadar faedah tahunan sebagai perpuluhan'),sym('t','tempoh dalam tahun')];}
        return set('consumer-mathematics',objective,['Gunakan kadar, tempoh dan syarat yang diberi dalam soalan.','Tukar kadar peratus kepada perpuluhan dan samakan tempoh dengan unit kadar.','Kenal pasti sama ada diminta jumlah matang, faedah, pulangan atau bayaran; jangan menyamakan semuanya.','Semak unit wang dan pembundaran yang diminta.'],formulas,symbols);
      }
      if(profiles[key])return set('chapter-'+key,objective,standard,...profiles[key]);
      const given=item?.formula||item?.originalFormula;
      return set('general',objective,['Baca arahan dan kenal pasti ukuran, nilai atau ciri yang diminta.','Gunakan maklumat serta hubungan yang dinyatakan dalam soalan dan panduan khusus di bawah.','Semak semua syarat, unit dan format jawapan sebelum memilih atau mengisi jawapan.'],[given?String(given):'Tiada satu formula umum yang boleh ditetapkan tanpa konteks; gunakan rumus atau definisi yang dinyatakan dalam soalan.'],[sym('Huruf atau label','mewakili titik, pemboleh ubah atau kuantiti seperti dinyatakan dalam soalan; tidak semestinya mempunyai makna yang sama antara soalan')]);
